    fn located(path: &str, hash: Hash256) -> LocatedEntry {
        LocatedEntry::new(
            RepoPath::from_utf8(path).expect("valid test repository path"),
            TreeEntry::blob(hash, false),
        )
    }

    fn capability_entry(sink: &[RetrievalDegradation]) -> &RetrievalDegradation {
        sink.iter()
            .find(|entry| entry.component == "capability_tier")
            .expect("a sub-Performance tier must record a capability_tier degradation")
    }

    /// The advice stays attached to the query shape that needs it, instead of
    /// retiring at the RRF constant. The rc061y ranking was right at 14
    /// entities while warning and wrong at 237 after the old threshold silenced
    /// the warning.
    #[test]
    fn description_query_guidance_is_not_tied_to_the_fusion_constant() {
        let mut sink = Vec::new();
        record_description_query_guidance(&mut sink);
        let entry = sink
            .iter()
            .find(|entry| entry.component == kin_mcp::negative::QUERY_SHAPE_COMPONENT)
            .expect("a description-shaped entity ranking must carry its guidance");
        assert!(
            entry
                .detail
                .contains("not one ranked entity was literally named"),
            "the entry must name the response fact it is about: {}",
            entry.detail
        );
        assert_eq!(
            entry.reason,
            kin_mcp::negative::DESCRIPTION_ENTITY_RANKING_REASON
        );
        assert!(
            entry
                .detail
                .contains("rows marked `semantic` carry vector evidence"),
            "all_fallback must not be misread as embeddings unused: {}",
            entry.detail
        );
        assert!(
            entry.remediation.contains("granularity: \"file\""),
            "the remediation must name the granularity that stayed useful: {}",
            entry.remediation
        );
        assert!(
            entry.remediation.contains("existing files[] rollup"),
            "the CLI must receive advice it can act on without a granularity flag: {}",
            entry.remediation
        );
    }

    /// The misread host in the surface a caller actually reads. A tier the host
    /// chose and a tier a failed probe chose must not produce the same entry:
    /// the first's remediation is sound advice, the second's told an operator
    /// with 128 GB to obtain more RAM.
    #[test]
    fn a_misread_host_is_a_distinct_capability_entry_from_a_small_one() {
        let mut misread = Vec::new();
        record_capability_tier_degradation(
            &CapabilityDetection {
                profile: LocateProfile::Minimal,
                forced_by_env: false,
                cores: Some(18),
                memory: Some(crate::capability::HostMemory::Undetected(
                    "sysctlbyname(hw.memsize) failed".to_string(),
                )),
            },
            &mut misread,
        );
        let entry = capability_entry(&misread);
        assert_eq!(entry.reason, "hardware_detection_failed");
        assert!(
            entry.detail.contains("sysctlbyname(hw.memsize) failed"),
            "the entry must name what failed: {}",
            entry.detail
        );
        assert!(
            !entry.remediation.contains("run on a host"),
            "a host that was never read must not be told to become a bigger host: {}",
            entry.remediation
        );

        let mut small = Vec::new();
        record_capability_tier_degradation(
            &CapabilityDetection {
                profile: LocateProfile::Minimal,
                forced_by_env: false,
                cores: Some(2),
                memory: Some(crate::capability::HostMemory::Detected(2.0)),
            },
            &mut small,
        );
        let entry = capability_entry(&small);
        assert_eq!(entry.reason, "minimal");
        assert!(entry.detail.contains("multihop"));
        assert!(entry.remediation.contains(">=8 cores"));
        // The entry may only name what the tier gates. It used to assert
        // "reranker" here, which was the false claim itself under test.
        for phantom in ["reranker", "prf", "ltr"] {
            assert!(
                !entry.detail.contains(phantom),
                "the capability entry must not claim {phantom}, which no tier gates: {}",
                entry.detail
            );
        }
    }

    /// The full pipeline on a host that was actually read stays silent, which
    /// is what keeps the two entries above meaningful.
    #[test]
    fn a_read_performance_host_records_no_capability_entry() {
        let mut sink = Vec::new();
        record_capability_tier_degradation(
            &CapabilityDetection {
                profile: LocateProfile::Performance,
                forced_by_env: false,
                cores: Some(18),
                memory: Some(crate::capability::HostMemory::Detected(128.0)),
            },
            &mut sink,
        );
        assert!(sink.is_empty());
    }

    /// FIR-2583. The tier remediation named `KIN_LOCATE_PROFILE` and stopped
    /// there, so a reader exported it in front of a CLI call and nothing
    /// changed: `CapabilityDetection::detect` reads the environment of the
    /// process it runs in, and on a repo with a daemon up that process is the
    /// daemon, which captured its environment when it started. The advice was
    /// unreachable from where the reader stood. It now says where the value is
    /// read, how to make a serving process read a new one, and what the tier
    /// actually gates, so nobody restarts a daemon expecting a description
    /// query to rank differently.
    #[test]
    fn the_capability_remediation_says_where_the_override_is_read_and_what_it_gates() {
        // The stranger's own container: 5 cores of quota and 12 GiB, scored
        // Standard, which is a sub-Performance tier and so discloses.
        let mut sink = Vec::new();
        record_capability_tier_degradation(
            &CapabilityDetection {
                profile: LocateProfile::Standard,
                forced_by_env: false,
                cores: Some(5),
                memory: Some(crate::capability::HostMemory::Detected(12.0)),
            },
            &mut sink,
        );
        let entry = capability_entry(&sink);
        assert_eq!(entry.reason, "standard");
        for required in [
            "KIN_LOCATE_PROFILE=performance",
            "read once at process start",
            "kin daemon stop",
            "multihop budget",
        ] {
            assert!(
                entry.remediation.contains(required),
                "the remediation must say {required:?}, got: {}",
                entry.remediation
            );
        }

        // The misread-host entry names the same variable, so it carries the
        // same reachability clause. Its own rule still holds: a host that was
        // never read is not told to become a bigger host.
        let mut misread = Vec::new();
        record_capability_tier_degradation(
            &CapabilityDetection {
                profile: LocateProfile::Minimal,
                forced_by_env: false,
                cores: Some(18),
                memory: Some(crate::capability::HostMemory::Undetected(
                    "sysctlbyname(hw.memsize) failed".to_string(),
                )),
            },
            &mut misread,
        );
        let misread_entry = capability_entry(&misread);
        assert!(
            misread_entry.remediation.contains("kin daemon stop"),
            "the misread entry names the same variable and must say the same thing about \
             reaching it: {}",
            misread_entry.remediation
        );
        assert!(
            !misread_entry.remediation.contains("run on a host"),
            "a host that was never read must not be told to become a bigger host: {}",
            misread_entry.remediation
        );

        // The control that keeps the strings above meaningful: a host on the
        // full tier records no entry at all, so this is not text every result
        // carries.
        let mut performance = Vec::new();
        record_capability_tier_degradation(
            &CapabilityDetection {
                profile: LocateProfile::Performance,
                forced_by_env: false,
                cores: Some(18),
                memory: Some(crate::capability::HostMemory::Detected(128.0)),
            },
            &mut performance,
        );
        assert!(
            performance.is_empty(),
            "the full tier narrows nothing and must stay silent, got {performance:?}"
        );
    }

    /// A ranked entity carrying the query's own classification, so the test
    /// drives [`classify_locate_match`] rather than asserting a hand-set kind.
    fn surface_hit(name: &str, kind: &str, score: f32, query: &str) -> LocateEntity {
        LocateEntity {
            entity_id: format!("id-{name}"),
            id_space: LocateIdSpace::Entity,
            artifact_path: None,
            kind: kind.to_string(),
            name: name.to_string(),
            signature: format!("def {name}(...)"),
            score,
            definition: true,
            span: Some([1, 9]),
            body: None,
            match_kind: Some(classify_locate_match(query, name, "text", None)),
            provenance: LocateProvenance {
                file: Some("linkgraph.py".to_string()),
                origin: "text".to_string(),
                cosine: Some(0.8),
            },
            matched_queries: Vec::new(),
        }
    }

    /// Rank a small entity set exactly as `build_entity_view` does: the surface
    /// penalty, then the shared ordering. Owner mass is 0 for every row, which
    /// is what it reads for every non-name hit in production too.
    fn surface_ranked(query: &str, hits: &[(&str, &str, f32)]) -> Vec<LocateEntity> {
        let mut ranked: Vec<(usize, LocateEntity)> = hits
            .iter()
            .enumerate()
            .map(|(rank, (name, kind, score))| (rank, surface_hit(name, kind, *score, query)))
            .collect();
        apply_entity_surface_penalty(&mut ranked, query);
        order_locate_entities(&mut ranked, query, |_| 0);
        ranked.into_iter().map(|(_, entity)| entity).collect()
    }

    fn surface_ranked_names(query: &str, hits: &[(&str, &str, f32)]) -> Vec<String> {
        surface_ranked(query, hits)
            .into_iter()
            .map(|entity| entity.name)
            .collect()
    }

    /// FIR-2582, the stranger's exact failure. On a five-module project a
    /// description of the dot-export code returned `_dot_escape`, `_blank` and
    /// `_clean_snippet` while `to_dot` was absent at rank 30 of 83: the private
    /// helpers carried more lexical mass than the exported function, and
    /// nothing at entity granularity looked at a name to tell them apart. The
    /// same query at file granularity put the module first, because the impl
    /// penalties there key on the path.
    #[test]
    fn a_description_ranks_the_public_entity_above_the_private_helpers() {
        let hits = [
            ("_dot_escape", "function", 1.0f32),
            ("_blank", "function", 0.9f32),
            ("to_dot", "function", 0.6f32),
        ];

        assert_eq!(
            surface_ranked_names("render the graph as dot output for graphviz", &hits),
            vec!["to_dot", "_dot_escape", "_blank"],
            "a description query must rank the exported function above the private helpers \
             it calls, even when they score higher on lexical mass"
        );

        // And the other half of the contract: naming a private symbol asks for
        // it, so the penalty must not touch it. The exact-name tier already
        // owns this case; the penalty stays out of its way rather than fighting
        // it, which is why the exemption reads the tier instead of a second
        // predicate.
        let by_name = surface_ranked("_dot_escape", &hits);
        assert_eq!(
            by_name
                .iter()
                .map(|entity| entity.name.as_str())
                .collect::<Vec<_>>(),
            vec!["_dot_escape", "to_dot", "_blank"],
            "a query that names a private helper exactly must still rank it first"
        );
        // The tier would put it first whether or not it was penalized, so the
        // exemption is only visible in the score the caller reads back. Assert
        // it, or removing the exemption changes what the surface reports and no
        // test says a word.
        assert_eq!(
            by_name[0].score, 1.0,
            "an exact-name hit must be reported at its own score, unpenalized"
        );
        assert_eq!(
            by_name[2].score,
            0.9 * 0.3,
            "while a private helper the query did not name still carries the penalty"
        );
    }

    /// The naming rule on its own, including the case that makes it a rule
    /// about surfaces rather than about underscores.
    #[test]
    fn a_dunder_is_language_protocol_and_a_leading_underscore_is_private() {
        assert_eq!(
            entity_surface_class("_dot_escape", "function"),
            Some("private_name")
        );
        assert_eq!(
            entity_surface_class("LinkGraph._blank", "method"),
            Some("private_name"),
            "the rule reads the entity's own name, not the owner it hangs off"
        );
        assert_eq!(
            entity_surface_class("_LinkRow__mangled", "method"),
            Some("private_name")
        );

        // `__init__` opens with an underscore and is the answer to "how is this
        // constructed". Demoting it would answer that with everything except
        // the constructor.
        assert_eq!(entity_surface_class("__init__", "method"), None);
        assert_eq!(entity_surface_class("LinkRow.__repr__", "method"), None);

        assert_eq!(
            entity_surface_class("test_to_dot", "function"),
            Some("test_support")
        );
        assert_eq!(
            entity_surface_class("roundtrip_test", "function"),
            Some("test_support")
        );
        assert_eq!(
            entity_surface_class("to_dot", "test"),
            Some("test_support"),
            "the graph's own Test kind says it too, whatever the name reads like"
        );

        // Controls: ordinary public API must not match, or the rule demotes
        // every candidate and orders nothing.
        assert_eq!(entity_surface_class("to_dot", "function"), None);
        assert_eq!(
            entity_surface_class("LinkGraph.ingest_directory", "method"),
            None
        );
        assert_eq!(entity_surface_class("", "function"), None);
    }

    fn native_change(
        parents: Vec<SemanticChangeId>,
        message: &str,
        entity_deltas: Vec<EntityDelta>,
        tree_deltas: Vec<TreeDelta>,
    ) -> SemanticChange {
        let admission_policy_delta = parents
            .is_empty()
            .then(|| AdmissionPolicyDelta::initialize(SharedAdmissionPolicy::empty(0)));
        let mut change = SemanticChange {
            id: SemanticChangeId::from_hash(Hash256::from_bytes([0; 32])),
            origin: ChangeOrigin::Native,
            parents,
            timestamp: Timestamp::now(),
            author: AuthorId::new("locate-test"),
            message: message.to_string(),
            entity_deltas,
            relation_deltas: Vec::new(),
            tree_deltas,
            admission_policy_delta,
            projected_files: Vec::new(),
            spec_link: None,
            evidence: Vec::new(),
            risk_summary: None,
            external_reference_deltas: Vec::new(),
        };
        change.id = kin_core::compute_semantic_change_id(&change).unwrap();
        change
    }

    fn persist_test_history(
        root: &std::path::Path,
        repository_name: &str,
        changes: Vec<SemanticChange>,
        bodies: &[(Hash256, &[u8])],
    ) -> RepositoryAuthorityManager<LocalFileBackend> {
        let repository_id = RepositoryId::new(repository_name).unwrap();
        let kindb = root.join("kindb");
        std::fs::create_dir(&kindb).unwrap();
        let manager = RepositoryAuthorityManager::open(
            repository_id.clone(),
            Arc::new(LocalFileBackend::new(kindb)),
        )
        .unwrap();
        for (digest, body) in bodies {
            manager.save_source_blob(*digest, body).unwrap();
        }
        let shared_policy = SharedAdmissionPolicy::empty(0);
        let workspace_id = WorkspaceId::from_uuid(uuid::Uuid::new_v4());
        let overlay =
            FrozenLocalOverlay::new(workspace_id, 0, AdmissionCase::Sensitive, Vec::new()).unwrap();
        let admission_policy = EffectiveAdmissionPolicyStamp {
            shared: shared_policy.stamp(),
            local: overlay.stamp(),
        };
        let main = RefName::branch(b"main").unwrap();
        let mut tree = ResolvedTree::default();
        let mut previous_target = None;
        let mut previous_tree_hash = None;
        for (index, change) in changes.into_iter().enumerate() {
            let prior_target = previous_target.clone();
            let prior_tree_hash = previous_tree_hash;
            tree = tree.apply(&change.tree_deltas).unwrap();
            let tree_hash = kin_model::compute_resolved_tree_hash(&tree).unwrap();
            let target = RefTarget::change(change.id);
            let lease = manager.read_authority();
            let transaction = RepositoryTransaction {
                schema_version: REPOSITORY_TRANSACTION_SCHEMA_VERSION,
                operation_id: OperationId::new(),
                repository_id: repository_id.clone(),
                expected_generation: lease.roots().generation,
                expected_roots: lease.roots().clone(),
                actor: AuthorId::new("locate-test"),
                reason: format!("persist exact locate history fixture: {}", change.message),
                external_objects: Vec::new(),
                git_authority_delta: None,
                changes: vec![change.clone()],
                aliases: Vec::new(),
                ref_mutations: vec![RefMutation {
                    name: main.clone(),
                    expected: prior_target
                        .clone()
                        .map_or(RefExpectation::MustNotExist, |target| {
                            RefExpectation::MustEqual { target }
                        }),
                    new_target: Some(target.clone()),
                    policy: RefUpdatePolicy::FastForwardOnly,
                }],
                default_ref_mutation: (index == 0).then(|| DefaultRefMutation {
                    expected: DefaultRefExpectation::MustBeUnset,
                    new_default: Some(main.clone()),
                }),
                workspace_mutation: Some(WorkspaceMutation {
                    workspace_id,
                    expected: if index == 0 {
                        WorkspaceExpectation::MustNotExist
                    } else {
                        WorkspaceExpectation::MustEqual {
                            generation: u64::try_from(index - 1).unwrap(),
                            head: WorkspaceHead::Symbolic {
                                target: main.clone(),
                            },
                            base_target: prior_target,
                            base_tree_hash: prior_tree_hash,
                            tree_hash: prior_tree_hash.unwrap(),
                            semantic_overlay_hash: kin_model::WorkspaceSemanticOverlay::default()
                                .identity_hash()
                                .unwrap(),
                            admission_policy: admission_policy.clone(),
                        }
                    },
                    new_generation: u64::try_from(index).unwrap(),
                    new_head: WorkspaceHead::Symbolic {
                        target: main.clone(),
                    },
                    new_base_target: Some(target.clone()),
                    new_base_tree_hash: Some(tree_hash),
                    tree_deltas: change.tree_deltas.clone(),
                    new_tree_hash: tree_hash,
                    semantic_delta: kin_model::WorkspaceSemanticDelta::new(
                        change.entity_deltas.clone(),
                        change.relation_deltas.clone(),
                    )
                    .unwrap(),
                    new_shared_admission_policy: shared_policy.clone(),
                    new_admission_policy: admission_policy.clone(),
                }),
                local_overlay_delta: (index == 0)
                    .then(|| FrozenLocalOverlayDelta::initialize(overlay.clone())),
                merge_transaction_delta: None,
                sealed_observation: None,
            };
            drop(lease);
            manager.commit_repository_transaction(transaction).unwrap();
            previous_target = Some(target);
            previous_tree_hash = Some(tree_hash);
        }
        manager
    }

    trait TestArtifactAdmission {
        fn put_opaque(&self, artifact: &OpaqueArtifact) -> kin_db::Result<()>;
    }

    impl TestArtifactAdmission for kin_db::InMemoryGraph {
        fn put_opaque(&self, artifact: &OpaqueArtifact) -> kin_db::Result<()> {
            let path = RepoPath::from_utf8(artifact.file_id.0.clone())
                .expect("valid test repository path");
            let new = kin_model::LocatedEntry::new(
                path.clone(),
                TreeEntry::blob(artifact.content_hash, false),
            );
            let tree_delta = match self.resolved_tree().artifact_at_path(&path).cloned() {
                Some(existing) if existing.entry == new.entry => None,
                Some(existing) => Some(TreeDelta::Updated {
                    artifact_id: existing.artifact_id,
                    old: existing.located_entry(),
                    new,
                }),
                None => Some(TreeDelta::Added {
                    artifact_id: ArtifactId::new(),
                    new,
                }),
            };
            if let Some(tree_delta) = tree_delta {
                self.apply_transaction_delta(&TransactionDelta {
                    entity_deltas: Vec::new(),
                    relation_deltas: Vec::new(),
                    tree_deltas: vec![tree_delta],
                    admission_policy_delta: None,
                    external_reference_deltas: Vec::new(),
                })?;
            }
            EntityStore::upsert_opaque_artifact(self, artifact)
        }
    }

    /// The dogfood store's shape: a docs artifact carrying the phrase, and a
    /// code entity whose NAME shares a word with it. That entity is what the
    /// ranking answered with while the artifact holding the actual sentence was
    /// unrepresentable, so the fixture keeps the competitor rather than testing
    /// against an empty field.
    fn artifact_shaped_graph() -> kin_db::InMemoryGraph {
        let graph = kin_db::InMemoryGraph::new();
        let entity = test_entity("fail", "bin/extract_workflow_steps.py", 1, 5);
        graph.upsert_entity(&entity).unwrap();
        admit_test_source(
            &graph,
            "bin/extract_workflow_steps.py",
            "def fail(message):\n    raise SystemExit(message)\n",
        );
        admit_test_source(
            &graph,
            "AGENTS.md",
            "# Verification Rule\n\nChecks That Cannot Fail\n\nFourteen traps have already \
             produced confident wrong answers in this workspace.\n",
        );
        // Text-index upserts are buffered; without the commit `text_search`
        // answers every term with zero hits and the fixture would prove nothing
        // about ranking.
        graph.flush_text_index().unwrap();
        graph
    }

    /// Run the fused pipeline exactly as the default serving profile does.
    ///
    /// Nothing is pinned on purpose. The parked attempt at this pinned
    /// `KIN_LOCATE_LEXICAL_FLOOR_READMIT=1`, which is the accuracy profile's
    /// default and not the shipped one, so its evidence read greener than the
    /// product could ever be: the stage it was asserting does not run for a real
    /// caller. A test for this ticket has to be able to fail the way the dogfood
    /// session failed.
    fn agent_locate(graph: &kin_db::InMemoryGraph, query: &str) -> LocateResult {
        run_with_graph_capture_budgeted(
            graph,
            None,
            query,
            false,
            10,
            true,
            Vec::new(),
            None,
            SnippetOptions::enabled(None),
            None,
            kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
            LocateScope::SOURCE_ONLY,
            LocateBudget::unbounded(),
        )
        .unwrap()
    }

    fn artifact_row<'a>(result: &'a LocateResult, path: &str) -> Option<&'a LocateEntity> {
        result
            .entities
            .iter()
            .find(|entity| entity.artifact_path.as_deref() == Some(path))
    }

    fn degradation<'a>(result: &'a LocateResult, reason: &str) -> Option<&'a RetrievalDegradation> {
        result
            .degradations
            .iter()
            .find(|event| event.component == "artifact_candidates" && event.reason == reason)
    }

    fn text_index_degradation(result: &LocateResult) -> Option<&RetrievalDegradation> {
        result
            .degradations
            .iter()
            .find(|event| event.component == "text_index")
    }

    /// The state a live daemon sits in between its own persistence flushes:
    /// documents staged into the lexical index and not committed.
    ///
    /// Deliberately NO `graph.flush_text_index()` here, and that absence is the
    /// whole fixture. Every other graph builder in this module makes that call
    /// by hand, with a comment saying that without it `text_search` answers
    /// every term with zero hits. A caller does not get to make it, which is why
    /// the pipeline has to.
    fn unflushed_prose_graph() -> kin_db::InMemoryGraph {
        let graph = kin_db::InMemoryGraph::new();
        let mut overview = test_entity("describe_layers", "pkg/overview.py", 1, 3);
        overview.doc_summary =
            Some("Nothing here opens a socket or speaks to a server over the network.".to_string());
        graph.upsert_entity(&overview).unwrap();
        let parsing = test_entity("normalize_title", "pkg/parsing.py", 1, 3);
        graph.upsert_entity(&parsing).unwrap();
        graph
    }

    /// FIR-2918. A prose term the graph holds has to be answerable from the
    /// index as the query finds it, not as a background timer will leave it.
    ///
    /// Measured on the product before this: a four-module store reported zero of
    /// seventeen entities text indexed at the moment a first English question
    /// arrived, seventeen of seventeen sixty seconds later, on one unchanged
    /// daemon process, and answered "No relevant files found." in between.
    #[test]
    #[serial_test::serial]
    fn a_docstring_term_answers_on_a_graph_whose_text_index_was_never_flushed() {
        let graph = unflushed_prose_graph();
        assert_eq!(
            graph.text_document_count(),
            0,
            "the fixture must start with nothing committed, or this test grades a flushed index"
        );

        let result = agent_locate(&graph, "socket");

        assert!(
            graph.text_document_count() > 0,
            "the query path left the lexical index empty, so no lexical evidence could have \
             ranked this answer"
        );
        assert!(
            result
                .files
                .iter()
                .any(|file| file.path == "pkg/overview.py"),
            "a term only this file's docstring carries did not retrieve it; got {:?}",
            result
                .files
                .iter()
                .map(|file| file.path.as_str())
                .collect::<Vec<_>>()
        );
        // The control that keeps the report from becoming noise: an index that
        // answered must not also be reported as a gap.
        assert!(
            text_index_degradation(&result).is_none(),
            "an index that answered was reported as a gap: {:?}",
            text_index_degradation(&result)
        );
    }

    /// The other half, and it has to be a separate test or the two hide each
    /// other. A graph with entities and no lexical index at all cannot answer a
    /// lexical question from graph truth, and the rule here is to report that
    /// rather than answer thin from somewhere else.
    #[test]
    #[serial_test::serial]
    fn a_graph_with_no_lexical_index_reports_the_gap_rather_than_answering_thin() {
        let source = unflushed_prose_graph();
        let snapshot = source.to_snapshot();
        let graph = kin_db::InMemoryGraph::from_snapshot_without_text_index(snapshot).unwrap();
        assert!(
            graph.entity_count() > 0,
            "the fixture must carry entities, or the gap report is about an empty graph"
        );

        let result = agent_locate(&graph, "socket");

        let reported = text_index_degradation(&result).unwrap_or_else(|| {
            panic!(
                "a graph with no lexical index answered without reporting the gap; ledger: {:?}",
                result
                    .degradations
                    .iter()
                    .map(|event| (event.component.as_str(), event.reason.as_str()))
                    .collect::<Vec<_>>()
            )
        });
        assert_eq!(reported.reason, "empty", "gap report: {reported:?}");
        assert!(
            reported.detail.contains("no documents"),
            "the report must say what is missing: {reported:?}"
        );
        assert!(
            !reported.remediation.is_empty(),
            "a gap report with no remediation tells a caller nothing to do: {reported:?}"
        );
    }

    /// A store whose answer lives in an artifact must be able to say so on the
    /// surface an agent reads. This is the dogfood session's exact failure,
    /// where a store proven by `kin_artifact_read` to hold a phrase answered
    /// queries for that phrase with Python function names.
    #[test]
    #[serial_test::serial]
    fn a_ranked_artifact_reaches_the_graph_native_entity_surface() {
        let graph = artifact_shaped_graph();
        let result = agent_locate(&graph, "Checks That Cannot Fail");

        let artifact = result
            .entities
            .iter()
            .find(|entity| entity.artifact_path.as_deref() == Some("AGENTS.md"))
            .unwrap_or_else(|| {
                panic!(
                    "the artifact holding the phrase must be a candidate; got {:?} from files {:?}",
                    result
                        .entities
                        .iter()
                        .map(|entity| (entity.name.as_str(), entity.id_space))
                        .collect::<Vec<_>>(),
                    result
                        .files
                        .iter()
                        .map(|file| file.path.as_str())
                        .collect::<Vec<_>>(),
                )
            });
        assert_eq!(artifact.id_space, LocateIdSpace::Artifact);
        assert_eq!(artifact.kind, "artifact");
        // No entity id, because there is no entity: a field named one holding
        // anything else is how a dead handle reaches an agent.
        assert!(artifact.entity_id.is_empty());
        assert_eq!(artifact.name, "AGENTS.md");
    }

    /// The control that keeps the change additive: an ordinary code query still
    /// answers with entities, each carrying a real id and the entity id space.
    #[test]
    #[serial_test::serial]
    fn entity_hits_are_unchanged_when_artifacts_can_also_rank() {
        let graph = artifact_shaped_graph();
        let result = agent_locate(&graph, "fail");

        let entity = result
            .entities
            .iter()
            .find(|entity| entity.name == "fail")
            .expect("a code query must still answer with its entity");
        assert_eq!(entity.id_space, LocateIdSpace::Entity);
        assert!(!entity.entity_id.is_empty());
        assert!(entity.artifact_path.is_none());
    }

    /// An artifact row serializes as the identity contract states: no
    /// `entity_id` key at all, an `artifact_path`, and an explicit `id_space`.
    /// Asserted on the JSON rather than the struct, because the omission is a
    /// serde attribute and the struct cannot show whether it took effect.
    #[test]
    fn artifact_rows_omit_entity_id_on_the_wire() {
        let file = LocateFileEntry {
            path: "docs/guide.md".to_string(),
            score: 12.5,
            signals: Vec::new(),
            spans: Vec::new(),
            symbols: Vec::new(),
            provenance: None,
            explain: Vec::new(),
            signal_scores: None,
            score_breakdown: None,
            matched_queries: Vec::new(),
        };
        let row = serde_json::to_value(artifact_locate_entity(&file, "guide")).unwrap();
        assert!(row.get("entity_id").is_none(), "serialized row: {row}");
        assert_eq!(row["id_space"], serde_json::json!("artifact"));
        assert_eq!(row["artifact_path"], serde_json::json!("docs/guide.md"));

        // The entity space is the default and stays off the wire, so every hit
        // that could rank before this field existed serializes unchanged.
        let mut entity = artifact_locate_entity(&file, "guide");
        entity.entity_id = "e1".to_string();
        entity.id_space = LocateIdSpace::Entity;
        entity.artifact_path = None;
        let row = serde_json::to_value(&entity).unwrap();
        assert_eq!(row["entity_id"], serde_json::json!("e1"));
        assert!(row.get("id_space").is_none());
        assert!(row.get("artifact_path").is_none());
    }

    /// Two artifacts in one ranking must both survive. Keyed on the raw
    /// `entity_id`, they share the empty string and all but the first are
    /// dropped, which looks exactly like artifacts still not being candidates.
    #[test]
    fn artifact_rows_dedupe_on_their_path_not_their_empty_id() {
        let row = |path: &str| {
            let file = LocateFileEntry {
                path: path.to_string(),
                score: 1.0,
                signals: Vec::new(),
                spans: Vec::new(),
                symbols: Vec::new(),
                provenance: None,
                explain: Vec::new(),
                signal_scores: None,
                score_breakdown: None,
                matched_queries: Vec::new(),
            };
            artifact_locate_entity(&file, "guide")
        };
        let first = row("docs/one.md");
        let second = row("docs/two.md");
        assert_ne!(first.identity_key(), second.identity_key());
        assert_eq!(first.identity_key(), "docs/one.md");
    }

    /// A multi-query fan-out fuses its variants by a per-row key. Keyed on the
    /// raw `entity_id`, every artifact in the ranking shares the empty string, so
    /// RRF collapses them all into one row and the rest vanish, which on the wire
    /// is indistinguishable from artifacts still being excluded. This is where
    /// that collapse actually happens, so this is where it is asserted.
    #[test]
    fn fusion_keeps_every_artifact_rather_than_collapsing_their_empty_ids() {
        let artifact = |path: &str| {
            let file = LocateFileEntry {
                path: path.to_string(),
                score: 1.0,
                signals: Vec::new(),
                spans: Vec::new(),
                symbols: Vec::new(),
                provenance: None,
                explain: Vec::new(),
                signal_scores: None,
                score_breakdown: None,
                matched_queries: Vec::new(),
            };
            artifact_locate_entity(&file, "doctrine")
        };
        let page = |entities: Vec<LocateEntity>| LocateResult {
            entities,
            ..Default::default()
        };
        let fused = fuse_locate_results(
            vec!["doctrine".to_string(), "doctrine traps".to_string()],
            vec![
                page(vec![artifact("AGENTS.md"), artifact("docs/traps.md")]),
                page(vec![artifact("docs/traps.md")]),
            ],
            locate_rrf_k(),
        );
        let paths: Vec<&str> = fused
            .entities
            .iter()
            .filter_map(|entity| entity.artifact_path.as_deref())
            .collect();
        assert_eq!(paths.len(), 2, "fused rows: {paths:?}");
        assert!(paths.contains(&"AGENTS.md"));
        assert!(paths.contains(&"docs/traps.md"));
    }

    /// Two matching artifacts in one ranking both reach the page, end to end.
    #[test]
    #[serial_test::serial]
    fn two_matching_artifacts_both_reach_the_page() {
        let graph = kin_db::InMemoryGraph::new();
        admit_test_source(
            &graph,
            "AGENTS.md",
            "Checks That Cannot Fail is doctrine.\n",
        );
        admit_test_source(
            &graph,
            "docs/traps.md",
            "More on Checks That Cannot Fail.\n",
        );
        graph.flush_text_index().unwrap();

        let result = agent_locate(&graph, "Checks That Cannot Fail");
        assert!(
            artifact_row(&result, "AGENTS.md").is_some(),
            "entities: {:?}",
            result
                .entities
                .iter()
                .map(|entity| entity.name.as_str())
                .collect::<Vec<_>>()
        );
        assert!(artifact_row(&result, "docs/traps.md").is_some());
    }

    /// The F15 shape, and the reason this ticket names the admit disclosure:
    /// `kin admit` promises the files it admits become queryable, and files with
    /// no entities and no embeddings answered nothing at all. They are their own
    /// text and nothing else, which is exactly the evidence this door opens on.
    #[test]
    #[serial_test::serial]
    fn admitted_entity_free_files_answer_for_their_own_text() {
        let graph = kin_db::InMemoryGraph::new();
        admit_test_source(
            &graph,
            "dogfood-note-1.md",
            "A dogfood note about admission.\n",
        );
        admit_test_source(&graph, "dogfood-sub/nested.md", "Nested dogfood note.\n");
        graph.flush_text_index().unwrap();

        let result = agent_locate(&graph, "dogfood note");
        assert!(
            !result.entities.is_empty(),
            "an admitted file must answer for its own text; files: {:?}",
            result
                .files
                .iter()
                .map(|file| file.path.as_str())
                .collect::<Vec<_>>()
        );
        assert!(result
            .entities
            .iter()
            .all(|entity| entity.id_space == LocateIdSpace::Artifact));
    }

    /// The same promise through the REAL ingest enrichment instead of a
    /// hand-rolled preview. Every fixture above hands `put_opaque` its full
    /// body as `text_preview`, which is a state ingest never produced: the
    /// enrichment pipeline stored every opaque artifact with no text at all,
    /// so on a real store the text index held only a path and a MIME type and
    /// every one of these green tests described a store that could not exist.
    /// This test routes the bytes through `IndexPipeline::index_any_content`,
    /// exactly what the daemon runs on admit, and puts the phrase past any
    /// head-sized preview so head-only retention fails it too.
    #[test]
    #[serial_test::serial]
    fn a_pipeline_enriched_docs_store_answers_for_deep_content() {
        let mut body = String::from("# Kin Ecosystem AGENTS.md\n\n");
        for index in 0..40 {
            body.push_str(&format!(
                "Ordinary paragraph {index} about workspace upkeep and lane hygiene, nothing \
                 doctrinal here.\n\n"
            ));
        }
        body.push_str("## Verification Rule\n\nChecks That Cannot Fail is doctrine here.\n");
        assert!(
            body.find("Checks That Cannot Fail").unwrap() > 2_000,
            "the phrase must sit beyond any head-sized preview"
        );

        let bytes = body.as_bytes();
        let indexed = kin_index::pipeline::IndexPipeline::new()
            .index_any_content(
                &FilePathId::new("AGENTS.md"),
                bytes,
                kin_blobs::digest(bytes),
            )
            .unwrap();
        let kin_index::pipeline::IndexedAny::OpaqueArtifact(artifact) = indexed else {
            panic!("markdown must take the opaque enrichment facet");
        };

        let graph = kin_db::InMemoryGraph::new();
        graph.put_opaque(&artifact).unwrap();
        graph.flush_text_index().unwrap();

        let result = agent_locate(&graph, "Checks That Cannot Fail");
        assert!(
            artifact_row(&result, "AGENTS.md").is_some(),
            "a pipeline-enriched docs store must answer for its own deep content; entities: {:?}",
            result
                .entities
                .iter()
                .map(|entity| entity.name.as_str())
                .collect::<Vec<_>>()
        );
    }

    /// The bound holds, and a short page says it was short. A page cut to its
    /// limit with nothing said reads as the store having only that much.
    #[test]
    #[serial_test::serial]
    fn the_artifact_admit_bound_holds_and_is_disclosed() {
        let _limit = kin_core::test_env::EnvVarGuard::set("KIN_LOCATE_ARTIFACT_ADMIT_LIMIT", "2");
        let graph = kin_db::InMemoryGraph::new();
        for index in 0..5 {
            admit_test_source(
                &graph,
                &format!("docs/trap-{index}.md"),
                "Checks That Cannot Fail, recorded here.\n",
            );
        }
        graph.flush_text_index().unwrap();

        let result = agent_locate(&graph, "Checks That Cannot Fail");
        let artifacts = result
            .entities
            .iter()
            .filter(|entity| entity.id_space == LocateIdSpace::Artifact)
            .count();
        assert_eq!(artifacts, 2, "entities: {:?}", result.entities.len());
        let event = degradation(&result, "over_admit_limit")
            .expect("a bounded page must say what the bound cut");
        assert!(event.detail.contains('5'), "detail: {}", event.detail);
        assert!(!event.remediation.is_empty());
    }

    /// An empty page over a store that HOLDS documents is an honest negative and
    /// stays one, but it must be able to say which honest negative it is: no
    /// documents here, or documents that do not say that.
    #[test]
    #[serial_test::serial]
    fn an_empty_page_over_an_artifact_store_says_the_artifacts_were_searched() {
        let graph = kin_db::InMemoryGraph::new();
        admit_test_source(
            &graph,
            "AGENTS.md",
            "Checks That Cannot Fail is doctrine.\n",
        );
        graph.flush_text_index().unwrap();

        let result = agent_locate(&graph, "photosynthesis chloroplast thylakoid");
        assert!(result.entities.is_empty());
        let event = degradation(&result, "no_text_match")
            .expect("an empty page over an artifact store must qualify itself");
        assert!(event.detail.contains('1'), "detail: {}", event.detail);
    }

    /// Controls that must hold or the change is not additive: a store with no
    /// artifacts is untouched, a query matching no artifact text admits none, and
    /// neither control raises the artifact disclosure.
    #[test]
    #[serial_test::serial]
    fn artifact_admission_leaves_unmatched_and_entity_only_rankings_alone() {
        let graph = artifact_shaped_graph();
        let unmatched = agent_locate(&graph, "photosynthesis chloroplast thylakoid");
        assert!(unmatched
            .entities
            .iter()
            .all(|entity| entity.id_space == LocateIdSpace::Entity));
        assert!(degradation(&unmatched, "over_admit_limit").is_none());

        let entity_only = kin_db::InMemoryGraph::new();
        let entity = test_entity("fail", "src/lib.rs", 1, 5);
        entity_only.upsert_entity(&entity).unwrap();
        entity_only.flush_text_index().unwrap();
        let result = agent_locate(&entity_only, "Checks That Cannot Fail");
        assert!(result
            .entities
            .iter()
            .all(|entity| entity.id_space == LocateIdSpace::Entity));
        assert!(degradation(&result, "no_text_match").is_none());
    }

    /// Test fixtures and licence text are tracked artifacts too, and a query
