    fn test_artifact_id(graph: &kin_db::InMemoryGraph, path: &str) -> ArtifactId {
        let path = RepoPath::from_utf8(path).expect("valid test repository path");
        graph
            .artifact_id_at_path(&path)
            .expect("test artifact must be explicitly admitted")
    }

    fn admit_test_source(graph: &kin_db::InMemoryGraph, path: &str, body: &str) {
        graph
            .put_opaque(&OpaqueArtifact {
                file_id: FilePathId::new(path),
                content_hash: kin_blobs::digest(body.as_bytes()),
                mime_type: Some("text/plain".to_string()),
                text_preview: Some(body.to_string()),
            })
            .unwrap();
    }

    #[test]
    fn result_provenance_fails_loud_when_tree_identity_is_missing() {
        let graph = kin_db::InMemoryGraph::new();
        let error = match collect_result_provenance(
            &graph,
            &[("README.md".to_string(), 1.0)],
            &HashMap::new(),
        ) {
            Err(error) => error,
            Ok(_) => {
                panic!("locate provenance must not fabricate a path-derived artifact identity")
            }
        };

        assert!(
            error
                .to_string()
                .contains("graph gap: no admitted artifact identity for README.md"),
            "unexpected graph-gap error: {error:#}"
        );
    }

    #[test]
    fn result_provenance_uses_explicitly_admitted_identity() {
        let graph = kin_db::InMemoryGraph::new();
        graph
            .put_opaque(&OpaqueArtifact {
                file_id: FilePathId::new("README.md"),
                content_hash: Hash256::from_bytes([0x81; 32]),
                mime_type: Some("text/markdown".to_string()),
                text_preview: Some("# Kin".to_string()),
            })
            .unwrap();
        let artifact_id = test_artifact_id(&graph, "README.md");

        let provenance =
            collect_result_provenance(&graph, &[("README.md".to_string(), 1.0)], &HashMap::new())
                .unwrap();

        assert_eq!(
            provenance["README.md"].objects[0].id,
            GraphNodeId::Artifact(artifact_id).to_string()
        );
    }

    fn hit(score: f32) -> Vec<FileHit> {
        vec![FileHit {
            score,
            spans: vec![],
        }]
    }

    /// Compare anchor-floor output against expected `(path, floor)` pairs with
    /// a float tolerance, since floors are products of `top_score` and a
    /// ratio rather than literal constants.
    fn assert_anchors_approx(actual: &[(String, f32)], expected: &[(&str, f32)]) {
        assert_eq!(
            actual.len(),
            expected.len(),
            "anchor count mismatch: {actual:?} vs {expected:?}"
        );
        for ((actual_path, actual_floor), (expected_path, expected_floor)) in
            actual.iter().zip(expected.iter())
        {
            assert_eq!(
                actual_path, expected_path,
                "anchor order mismatch: {actual:?} vs {expected:?}"
            );
            assert!(
                (actual_floor - expected_floor).abs() < 1e-4,
                "floor mismatch for {actual_path}: {actual_floor} vs {expected_floor}"
            );
        }
    }

    // ── Graph-native entity surface + cursor paging (static shape) ──

    fn mk_locate_entity(name: &str, score: f32, definition: bool) -> LocateEntity {
        LocateEntity {
            entity_id: format!("id-{name}"),
            id_space: LocateIdSpace::Entity,
            artifact_path: None,
            kind: "function".to_string(),
            name: name.to_string(),
            signature: format!("fn {name}()"),
            score,
            definition,
            span: Some([10, 20]),
            body: Some(format!("fn {name}() {{ /* … */ }}")),
            match_kind: None,
            provenance: LocateProvenance {
                file: Some(format!("src/{name}.rs")),
                origin: "vector".to_string(),
                cosine: Some(0.5),
            },
            matched_queries: Vec::new(),
        }
    }

    fn ranking(n: usize) -> Vec<LocateEntity> {
        (0..n)
            .map(|i| mk_locate_entity(&format!("e{i}"), 1.0 - i as f32 * 0.01, true))
            .collect()
    }

    fn file_ranking(n: usize) -> Vec<LocateFileEntry> {
        (0..n)
            .map(|index| {
                serde_json::from_value(serde_json::json!({
                    "path": format!("src/f{index}.rs"),
                    "score": 1.0 - index as f32 * 0.01,
                }))
                .expect("minimal file entry")
            })
            .collect()
    }

    #[test]
    fn locate_entity_serializes_entity_centric_with_file_as_provenance() {
        let result = LocateResult {
            entities: vec![mk_locate_entity("parse_config", 0.9, true)],
            total_ranked: 1,
            page: 0,
            files: Vec::new(),
            ..Default::default()
        };
        let v: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&result).unwrap()).unwrap();
        let e = &v["entities"][0];
        assert_eq!(e["entity_id"], "id-parse_config");
        assert_eq!(e["kind"], "function");
        assert_eq!(e["name"], "parse_config");
        assert_eq!(e["signature"], "fn parse_config()");
        assert!(e["body"].as_str().unwrap().contains("parse_config"));
        // File is provenance, never a top-level field on the entity.
        assert_eq!(e["provenance"]["file"], "src/parse_config.rs");
        assert!(e.get("file").is_none());
        assert_eq!(v["total_ranked"], 1);
        // Empty file list + zero/None paging fields are omitted from the wire.
        assert!(v.get("files").is_some()); // files is always serialized
        assert!(v.get("next_cursor").is_none());
        assert!(v.get("page").is_none()); // page == 0 is skipped
    }

    #[test]
    fn empty_entities_are_omitted_from_serialized_output() {
        let result = LocateResult {
            files: Vec::new(),
            ..Default::default()
        };
        let v: serde_json::Value =
            serde_json::from_str(&serde_json::to_string(&result).unwrap()).unwrap();
        // Human/in-process path: no entity surface leaks into the JSON.
        assert!(v.get("entities").is_none());
        assert!(v.get("total_ranked").is_none());
    }

    #[test]
    fn apply_entity_page_windows_first_page_and_emits_next_cursor() {
        let mut result = LocateResult {
            entities: ranking(20),
            ..Default::default()
        };
        apply_entity_page(&mut result, "abc123", 0, 6);
        assert_eq!(result.entities.len(), 6);
        assert_eq!(result.page, 0);
        assert_eq!(result.total_ranked, 20);
        // First page holds the top-ranked entity; more remain → next_cursor set.
        assert_eq!(result.entities[0].name, "e0");
        assert_eq!(result.next_cursor.as_deref(), Some("v2.abc123.1.6.6"));
    }

    #[test]
    fn apply_entity_page_last_page_has_no_next_cursor() {
        let mut result = LocateResult {
            entities: ranking(10),
            ..Default::default()
        };
        // page 1 of size 6 over 10 entities → 4 remaining, then done.
        apply_entity_page(&mut result, "k", 1, 6);
        assert_eq!(result.entities.len(), 4);
        assert_eq!(result.page, 1);
        assert_eq!(result.total_ranked, 10);
        assert_eq!(result.entities[0].name, "e6");
        assert!(result.next_cursor.is_none());
    }

