    #[test]
    fn apply_file_page_counts_files_clears_entities_and_uses_absolute_offset() {
        let mut result = LocateResult {
            entities: ranking(7),
            files: file_ranking(5),
            ..Default::default()
        };
        apply_file_page_at_offset(&mut result, "files", 1, 2, 2);
        assert!(
            result.entities.is_empty(),
            "file mode has one primary collection"
        );
        assert_eq!(
            result
                .files
                .iter()
                .map(|file| file.path.as_str())
                .collect::<Vec<_>>(),
            vec!["src/f2.rs", "src/f3.rs"]
        );
        assert_eq!(result.total_ranked, 5, "file count, not entity count");
        assert_eq!(result.page, 1);
        assert_eq!(result.next_cursor.as_deref(), Some("v2.files.2.4.2"));

        let mut narrow = LocateResult {
            files: file_ranking(5),
            ..Default::default()
        };
        apply_file_page_at_offset(&mut narrow, "files", 1, 1, 2);
        assert_eq!(narrow.files[0].path, "src/f2.rs");
        assert_eq!(
            narrow.next_cursor.as_deref(),
            Some("v2.files.2.3.1"),
            "a width override changes only how many files are emitted"
        );
    }

    #[test]
    fn locate_cursor_round_trips_width_and_accepts_legacy_tokens() {
        let cursor = LocateCursor {
            key: "deadbeefcafef00d".to_string(),
            page: 7,
            next_offset: Some(42),
            page_size: Some(6),
        };
        let token = cursor.encode();
        assert_eq!(token, "v2.deadbeefcafef00d.7.42.6");
        assert_eq!(LocateCursor::decode(&token), Some(cursor));
        assert_eq!(
            LocateCursor::decode("deadbeefcafef00d.7"),
            Some(LocateCursor {
                key: "deadbeefcafef00d".to_string(),
                page: 7,
                next_offset: None,
                page_size: None,
            }),
            "old two-part cursors must keep using the cached-width fallback"
        );
        // Garbage / non-numeric page / empty key → None (never a silent page 0).
        assert!(LocateCursor::decode("nodelimiter").is_none());
        assert!(LocateCursor::decode("key.notanumber").is_none());
        assert!(LocateCursor::decode(".5").is_none());
        assert!(LocateCursor::decode("key.1.0").is_none());
        assert!(LocateCursor::decode("key.nope.6").is_none());
        assert!(LocateCursor::decode("key.1.6").is_none());
    }

    #[test]
    fn entity_window_can_resume_from_a_budget_adjusted_offset() {
        let mut result = LocateResult {
            entities: ranking(20),
            ..Default::default()
        };
        apply_entity_page_at_offset(&mut result, "k", 2, 3, 8);
        assert_eq!(
            result
                .entities
                .iter()
                .map(|entity| entity.name.as_str())
                .collect::<Vec<_>>(),
            vec!["e8", "e9", "e10"]
        );
        assert_eq!(result.next_cursor.as_deref(), Some("v2.k.3.11.3"));
    }

    #[test]
    fn locate_cursor_keys_are_fresh_and_keep_a_scoped_fingerprint() {
        let a = locate_cursor_key("find the parser", Some("HEAD"), 42, "ranking+bodies");
        let b = locate_cursor_key("find the parser", Some("HEAD"), 42, "ranking+bodies");
        assert_ne!(
            a, b,
            "two fresh same-query rankings must not overwrite one cache slot"
        );
        assert_ne!(
            &a[16..],
            &b[16..],
            "the per-ranking nonce is the cache isolation boundary"
        );
        assert_eq!(
            &a[..16],
            &b[..16],
            "equal stable inputs retain one diagnostic fingerprint"
        );
        let fingerprint = |text, reference, version, mode| {
            locate_cursor_fingerprint(text, reference, version, mode)
        };
        // Query, ref, graph version, and projection remain visible in the stable
        // fingerprint even though freshness, not this subset, provides isolation.
        assert_ne!(
            fingerprint("find the parser", Some("HEAD"), 42, "ranking+bodies"),
            fingerprint("other query", Some("HEAD"), 42, "ranking+bodies")
        );
        assert_ne!(
            fingerprint("find the parser", Some("HEAD"), 42, "ranking+bodies"),
            fingerprint("find the parser", Some("main"), 42, "ranking+bodies")
        );
        assert_ne!(
            fingerprint("find the parser", Some("HEAD"), 42, "ranking+bodies"),
            fingerprint("find the parser", Some("HEAD"), 43, "ranking+bodies")
        );
    }

    /// The projection mode joins the cursor key, so one query at one graph version
    /// cannot serve two different projections from a single cached ranking.
    ///
    /// There are THREE projections, and the first version of this fix keyed on a
    /// `bodies` bool, which can only separate two. `bodies` is false both for the
    /// coordinates-only agent ranking and for the legacy path that projects no
    /// `entities[]` at all, so those two collided: a legacy request overwrote the
    /// agent's cached ranking with an empty one, and the agent's own cursor was
    /// then served that empty page from cache with no re-run. All three must be
    /// mutually distinct, which is what this asserts.
    #[test]
    fn locate_cursor_key_separates_every_projection_mode() {
        let key = |mode| locate_cursor_fingerprint("find the parser", Some("HEAD"), 42, mode);
        let none = key(projection_mode(false, false));
        let ranking = key(projection_mode(true, false));
        let with_bodies = key(projection_mode(true, true));

        assert_ne!(
            ranking, with_bodies,
            "include_snippet true/false must not collide on one cache entry"
        );
        // The pair the `bodies` bool could not tell apart. A real ranking and an
        // empty one sharing a key is how a legacy caller emptied an agent's cursor.
        assert_ne!(
            none, ranking,
            "the no-projection mode must not share a key with the agent ranking"
        );
        assert_ne!(none, with_bodies);

        // Deterministic within a fingerprint; the mode is the ONLY difference above.
        assert_eq!(
            ranking,
            key(projection_mode(true, false)),
            "the diagnostic fingerprint must stay deterministic within a mode"
        );
    }

    #[test]
    fn cursor_continuations_keep_the_structured_output_surface() {
        assert!(locate_outputs_json(true, None));
        assert!(
            locate_outputs_json(false, Some("opaque-cursor")),
            "documented bare `kin locate --next` must render entities, not replay files[]"
        );
        assert!(!locate_outputs_json(false, None));
    }

    #[test]
    fn bare_cursor_omits_false_explain_and_explicit_explain_survives() {
        assert_eq!(locate_explain_request(false, None), Some(false));
        assert_eq!(locate_explain_request(true, None), Some(true));
        assert_eq!(locate_explain_request(false, Some("cursor")), None);
        assert_eq!(locate_explain_request(true, Some("cursor")), Some(true));
    }

    /// `bodies` alone cannot distinguish the three projections, which is the whole
    /// reason the key takes a mode token.
    #[test]
    fn projection_mode_distinguishes_the_no_projection_case_from_a_bodiless_ranking() {
        assert_eq!(projection_mode(true, true), "ranking+bodies");
        assert_eq!(projection_mode(true, false), "ranking");
        assert_eq!(projection_mode(false, false), "none");
        // The trap: both have bodies == false.
        assert_ne!(projection_mode(true, false), projection_mode(false, false));
        // `SnippetOptions` agrees with the free function for each constructor.
        assert_eq!(SnippetOptions::default().projection_mode(), "none");
        assert_eq!(
            SnippetOptions::enabled(None).projection_mode(),
            "ranking+bodies"
        );
        assert_eq!(
            SnippetOptions::enabled(None)
                .without_bodies()
                .projection_mode(),
            "ranking"
        );
    }

    fn fusion_entity(id: &str, path: &str, score: f32) -> LocateEntity {
        LocateEntity {
            entity_id: id.to_string(),
            id_space: LocateIdSpace::Entity,
            artifact_path: None,
            kind: "function".to_string(),
            name: id.to_string(),
            signature: String::new(),
            score,
            definition: true,
            span: None,
            body: None,
            match_kind: None,
            provenance: LocateProvenance {
                file: Some(path.to_string()),
                origin: String::new(),
                cosine: None,
            },
            matched_queries: Vec::new(),
        }
    }

    fn fusion_result(entities: Vec<LocateEntity>) -> LocateResult {
        LocateResult {
            entities,
            ..Default::default()
        }
    }

    #[test]
    fn rrf_fuse_sums_contributions_and_attributes_lists() {
        // "a" is rank 0 in list 0 and rank 1 in list 1; "b" only in list 1.
        let lists = vec![vec!["a", "c"], vec!["b", "a"]];
        let mut fused = rrf_fuse(&lists, |s| s.to_string(), 60.0);
        fused.sort_by(|(_, _, sa), (_, _, sb)| {
            sb.partial_cmp(sa).unwrap_or(std::cmp::Ordering::Equal)
        });
        // "a" surfaced in both lists → highest fused score and both list indices.
        let (top, lists_of_top, _score) = &fused[0];
        assert_eq!(*top, "a");
        assert_eq!(lists_of_top, &vec![0, 1]);
        // Singleton keys carry exactly one contributing list.
        let b = fused.iter().find(|(k, _, _)| *k == "b").unwrap();
        assert_eq!(b.1, vec![1]);
    }

    #[test]
    fn fuse_locate_results_single_variant_is_passthrough() {
        let result = fusion_result(vec![
            fusion_entity("e1", "src/a.rs", 2.0),
            fusion_entity("e2", "src/b.rs", 1.0),
        ]);
        let fused =
            fuse_locate_results(vec!["only query".to_string()], vec![result], locate_rrf_k());
        // No fusion: order and records untouched, no attribution emitted.
        assert_eq!(fused.entities.len(), 2);
        assert_eq!(fused.entities[0].entity_id, "e1");
        assert!(fused.queries.is_empty());
        assert!(fused.entities.iter().all(|e| e.matched_queries.is_empty()));
    }

    #[test]
    fn fuse_locate_results_unions_and_attributes_variants() {
        // v0 ranks e1 > e2; v1 ranks e3 > e1. e1 appears in both → should win.
        let v0 = fusion_result(vec![
            fusion_entity("e1", "src/one.rs", 5.0),
            fusion_entity("e2", "src/two.rs", 4.0),
        ]);
        let v1 = fusion_result(vec![
            fusion_entity("e3", "src/three.rs", 5.0),
            fusion_entity("e1", "src/one.rs", 3.0),
        ]);
        let variants = vec!["identifier query".to_string(), "behavior query".to_string()];
        let fused = fuse_locate_results(variants.clone(), vec![v0, v1], 60.0);

        assert_eq!(fused.queries, variants);
        // e1 (in both variants) fuses to the top.
        assert_eq!(fused.entities[0].entity_id, "e1");
        assert_eq!(
            fused.entities[0].matched_queries,
            vec!["identifier query".to_string(), "behavior query".to_string()]
        );
        // Union covers every distinct entity across the variants.
        let ids: Vec<&str> = fused
            .entities
            .iter()
            .map(|e| e.entity_id.as_str())
            .collect();
        assert!(ids.contains(&"e1") && ids.contains(&"e2") && ids.contains(&"e3"));
        // Single-variant hits attribute to exactly the variant that surfaced them.
        let e2 = fused.entities.iter().find(|e| e.entity_id == "e2").unwrap();
        assert_eq!(e2.matched_queries, vec!["identifier query".to_string()]);
        let e3 = fused.entities.iter().find(|e| e.entity_id == "e3").unwrap();
        assert_eq!(e3.matched_queries, vec!["behavior query".to_string()]);
    }

    #[test]
    fn bound_fused_declaration_keeps_primary_budget_and_order() {
        let entry = |path: &str, score: f32| -> LocateFileEntry {
            serde_json::from_value(serde_json::json!({ "path": path, "score": score }))
                .expect("minimal file entry deserializes")
        };
        let mut v0 = LocateResult::default();
        v0.files = vec![entry("a.go", 3.0), entry("b.go", 2.0), entry("c.go", 1.0)];
        let mut v1 = LocateResult::default();
        v1.files = vec![entry("c.go", 9.0), entry("d.go", 8.0), entry("e.go", 7.0)];
        let variants = vec!["broad".to_string(), "sharp".to_string()];
        let mut fused = fuse_locate_results(variants, vec![v0, v1], 60.0);
        assert_eq!(fused.files.len(), 5, "union widens before the bound");
        assert_eq!(
            fused.files[0].path, "c.go",
            "corroborated file fuses to the top"
        );
        bound_fused_declaration_to_primary(&mut fused, 3, false);
        assert_eq!(
            fused.files.len(),
            3,
            "auto fusion must not widen the declaration"
        );
        assert_eq!(
            fused.files[0].path, "c.go",
            "bounded list keeps the fused order"
        );
        bound_fused_declaration_to_primary(&mut fused, 10, false);
        assert_eq!(fused.files.len(), 3, "larger budget is a no-op");
    }

    /// A ranking whose emitted order is deliberately not score-descending, the
    /// shape `adaptive_cap` produces when it appends a pre-compression readmit
    /// (strong uncompressed evidence, compressed live score) below a
    /// corroborated row that scored lower.
    fn non_monotonic_ranking() -> LocateResult {
        let entry = |path: &str, score: f32| -> LocateFileEntry {
            serde_json::from_value(serde_json::json!({
                "path": path,
                "score": score,
                "signals": ["lexical", "graph"],
            }))
            .expect("minimal file entry deserializes")
        };
        let mut result = LocateResult::default();
        result.files = vec![
            entry("src/top.rs", 120.00),
            entry("src/corroborated.rs", 45.79),
            entry("src/readmitted.rs", 85.10),
        ];
        result
    }

    #[test]
    fn locate_text_rows_keep_ranked_order_over_printed_score() {
        let result = non_monotonic_ranking();
        let lines = locate_text_lines(&result, false, "");
        let paths: Vec<&str> = lines
            .iter()
            .map(|line| line.split_whitespace().nth(1).unwrap())
            .collect();
        assert_eq!(
            paths,
            vec!["src/top.rs", "src/corroborated.rs", "src/readmitted.rs"],
            "rows follow the composed ranking, not the printed score: {lines:?}"
        );
        assert!(
            lines[0].starts_with("    1. "),
            "rank is explicit and 1-based: {:?}",
            lines[0]
        );
        assert!(
            lines[2].starts_with("    3. "),
            "rank keeps counting with the emitted order: {:?}",
            lines[2]
        );
    }

    #[test]
    fn locate_text_rows_omit_incomparable_score_by_default() {
        let lines = locate_text_lines(&non_monotonic_ranking(), false, "");
        for line in &lines {
            assert!(
                !line.contains("score:"),
                "a cross-row-incomparable score must not imply a sort key: {line:?}"
            );
            assert!(
                line.contains("(signals: lexical, graph)"),
                "signals still explain why a row was admitted: {line:?}"
            );
        }
    }

    #[test]
    fn locate_text_rows_carry_score_under_explain() {
        let lines = locate_text_lines(&non_monotonic_ranking(), true, "");
        assert!(
            lines[1].contains("(score: 45.79, signals: lexical, graph)"),
            "explain keeps the score as a diagnostic: {:?}",
            lines[1]
        );
        assert!(
            lines[2].contains("(score: 85.10, signals: lexical, graph)"),
            "explain keeps the score as a diagnostic: {:?}",
            lines[2]
        );
    }

    /// A ranked row carrying named symbols, so the file surface can be asked
    /// what evidence it rests on.
    fn row_with_symbols(path: &str, symbols: &[(&str, &str)]) -> LocateFileEntry {
        serde_json::from_value(serde_json::json!({
            "path": path,
            "score": 10.0,
            "signals": ["lexical", "graph"],
            "symbols": symbols
                .iter()
                .map(|(name, origin)| serde_json::json!({
                    "name": name,
                    "score": 1.0,
                    "kind": "function",
                    "definition": true,
                    "origin": origin,
                }))
                .collect::<Vec<_>>(),
        }))
        .expect("file entry with symbols deserializes")
    }

    /// A stranger's first `kin locate` on axum printed 1,400 characters of
    /// coverage warnings ahead of 432 characters of answer. Collapsed, the
    /// answer is first; nothing is dropped, because `--explain` still prints
    /// every note in full.
    #[test]
    fn coverage_notes_collapse_to_one_line_that_names_them() {
        let mut result = LocateResult::default();
        result.degradations = vec![
            RetrievalDegradation {
                component: "capability_tier".to_string(),
                reason: "standard".to_string(),
                detail: "graph multihop budget narrowed".to_string(),
                remediation: "set KIN_LOCATE_PROFILE=performance".to_string(),
            },
            RetrievalDegradation {
                component: "graph_role_filter".to_string(),
                reason: "tests_withheld".to_string(),
                detail: "134 test-role source path(s) were kept out of ranking".to_string(),
                remediation: "pass include_tests".to_string(),
            },
        ];
        let notes = coverage_notes(&result);
        assert_eq!(notes.len(), 2, "both notes survive collapsing");

        let summary = collapsed_notes_line(&notes).expect("two notes collapse to a line");
        assert!(
            summary.contains("2 notes"),
            "the count is the point of the line: {summary}"
        );
        assert!(
            summary.contains("capability_tier") && summary.contains("graph_role_filter"),
            "and the components are named, so a reader can tell whether theirs is in \
             there without re-running: {summary}"
        );
        assert!(
            summary.contains("--explain"),
            "the full text has to be reachable and the line has to say how: {summary}"
        );
        assert!(
            !summary.contains("134 test-role"),
            "the detail is what was collapsed; leaving it in collapses nothing: {summary}"
        );
        // The full text is what --explain prints, unchanged.
        assert!(
            notes[1].full.contains("134 test-role source path(s)")
                && notes[1].full.contains("pass include_tests"),
            "detail and remediation both survive into the explain form: {}",
            notes[1].full
        );

        // The decision between the two lengths, which is what the printing
        // actually calls. Grading the two halves alone left a mutation that
        // deleted the collapse from the default path green in both of them.
        let default_lines = coverage_note_lines(&result, false);
        assert_eq!(
            default_lines.len(),
            1,
            "the default path emits exactly one line, not one per note: {default_lines:?}"
        );
        assert!(
            default_lines[0].contains("2 notes") && default_lines[0].contains("--explain"),
            "and that line is the summary: {}",
            default_lines[0]
        );
        let explained_lines = coverage_note_lines(&result, true);
        assert_eq!(
            explained_lines.len(),
            2,
            "--explain emits every note: {explained_lines:?}"
        );
        assert!(
            explained_lines[1].contains("134 test-role source path(s)"),
            "in full: {}",
            explained_lines[1]
        );
        // The join, over the real set rather than the two ends. Every component
        // the summary names has to appear in the text --explain prints, or the
        // summary is pointing at something a reader cannot find.
        let mut covered = LocateResult::default();
        covered.semantic_coverage = Some(
            serde_json::from_value(serde_json::json!({
                "complete": false,
                "note": "no vector index is attached",
                "indexed": 0,
                "total": 7790,
                "pending": 0,
            }))
            .expect("minimal coverage deserializes"),
        );
        covered.degradations = result.degradations.clone();
        let summary = collapsed_notes_line(&coverage_notes(&covered))
            .expect("three notes collapse to a line");
        let explained = coverage_note_lines(&covered, true).join("\n");
        for note in coverage_notes(&covered) {
            assert!(
                summary.contains(&note.component),
                "the summary names every note: {summary} is missing {}",
                note.component
            );
            assert!(
                explained.contains(&note.component),
                "and --explain carries every name the summary used: {explained} is missing {}",
                note.component
            );
        }
        assert!(
            coverage_note_lines(&LocateResult::default(), false).is_empty()
                && coverage_note_lines(&LocateResult::default(), true).is_empty(),
            "a clean answer emits nothing on either path"
        );

        assert!(
            collapsed_notes_line(&[]).is_none(),
            "a clean answer prints no summary at all"
        );
        let one = collapsed_notes_line(&notes[..1]).expect("one note still collapses");
        assert!(
            one.contains("1 note on") && one.contains("read it."),
            "the singular reads as a sentence: {one}"
        );
    }

    /// `kin locate "Router path_router"` inside a Flask store returned six
    /// confident-looking Flask paths, and the reverse control did the same.
    /// Scoping was right in both directions. Nothing on the rows said that
    /// nothing had matched.
    #[test]
    fn rows_say_what_evidence_they_rest_on_and_a_weak_answer_says_so() {
        let named = row_with_symbols("axum/src/routing/path_router.rs", &[("PathRouter", "")]);
        let vectored = row_with_symbols("axum/src/routing/mod.rs", &[("Endpoint", "vector")]);
        let fallback = row_with_symbols("axum/src/json.rs", &[("Json", "")]);

        assert_eq!(
            file_row_match_kind(&named, "where is PathRouter built"),
            LocateMatchKind::Name,
            "a query naming a symbol in the file is a named match"
        );
        assert_eq!(
            file_row_match_kind(&named, "where is the path_router built"),
            LocateMatchKind::TextFallback,
            "and `path_router` does not name `PathRouter`: the query tokenizer splits on \
             every character that is not alphanumeric or an underscore, so the underscore \
             stays inside the token and the two are different words. Asserting otherwise \
             would pin a claim `query_names_entity` does not make."
        );
        assert_eq!(
            file_row_match_kind(&vectored, "how does routing dispatch"),
            LocateMatchKind::Semantic,
            "vector provenance is a weaker claim than a name and a stronger one than none"
        );
        assert_eq!(
            file_row_match_kind(&fallback, "Blueprint werkzeug wsgi_app"),
            LocateMatchKind::TextFallback,
            "nothing named and nothing from the vector pool is a text fallback"
        );
        assert_eq!(
            file_row_match_kind(
                &serde_json::from_value::<LocateFileEntry>(serde_json::json!({
                    "path": "a.rs", "score": 1.0, "signals": []
                }))
                .expect("bare entry deserializes"),
                "PathRouter"
            ),
            LocateMatchKind::TextFallback,
            "a row with no attributed symbols reads as the weaker claim, not the flattering one"
        );

        // A file holding the named symbol keeps the named verdict whatever else
        // it holds, so the strongest symbol decides the row.
        let mixed = row_with_symbols("axum/src/lib.rs", &[("Unrelated", ""), ("Router", "")]);
        assert_eq!(
            file_row_match_kind(&mixed, "Router"),
            LocateMatchKind::Name,
            "the strongest symbol decides the row"
        );

        let mut strong = LocateResult::default();
        strong.files = vec![named.clone(), fallback.clone()];
        assert!(
            answer_floor_note(&strong, "where is PathRouter built").is_none(),
            "one row over the floor is enough; the rest are its neighbours"
        );

        let mut weak = LocateResult::default();
        weak.files = vec![fallback.clone(), named.clone()];
        let note = answer_floor_note(&weak, "Blueprint werkzeug wsgi_app")
            .expect("an answer where nothing matched says so");
        assert!(
            note.contains("answer floor") && note.contains("symbol this query named"),
            "the floor is named rather than left as a number: {note}"
        );
        assert!(
            note.contains("2 rank on lexical and graph signals alone"),
            "and the reader is told how many rows it covers: {note}"
        );

        let lines = locate_text_lines(&weak, false, "Blueprint werkzeug wsgi_app");
        assert!(
            lines[0].ends_with("[lexical and graph only]"),
            "every row carries its label, so an absent one is a bug rather than good news: {:?}",
            lines[0]
        );
        let named_lines = locate_text_lines(&strong, false, "where is PathRouter built");
        assert!(
            named_lines[0].ends_with("[named match]"),
            "and a row the query named says so: {:?}",
            named_lines[0]
        );
        assert!(
            named_lines[0].contains("(signals: lexical, graph)"),
            "the label is appended, so the row shape other surfaces pin is unchanged: {:?}",
            named_lines[0]
        );

        assert!(
            answer_floor_note(&LocateResult::default(), "anything").is_none(),
            "an empty result has its own empty state and needs no floor note"
        );
    }

    #[test]
    fn locate_text_order_matches_json_order() {
        let result = non_monotonic_ranking();
        let json: serde_json::Value =
            serde_json::to_value(&result).expect("locate result serializes");
        let json_paths: Vec<String> = json["files"]
            .as_array()
            .expect("files array")
            .iter()
            .map(|f| f["path"].as_str().expect("path string").to_string())
            .collect();
        let text_paths: Vec<String> = locate_text_lines(&result, false, "")
            .iter()
            .map(|line| line.split_whitespace().nth(1).unwrap().to_string())
            .collect();
        assert_eq!(
            text_paths, json_paths,
            "the human and JSON surfaces must present one ranking"
        );
    }

    #[test]
    fn locate_text_indents_explain_reasons_under_their_row() {
        let mut result = non_monotonic_ranking();
        result.files[0].explain = vec!["seeded by entity resolve".to_string()];
        let lines = locate_text_lines(&result, true, "");
        assert!(lines[0].contains("src/top.rs"), "{:?}", lines[0]);
        assert_eq!(
            lines[1], "    - seeded by entity resolve",
            "reasons stay attached to the row above them"
        );
        assert!(
            lines[2].contains("src/corroborated.rs"),
            "the next ranked row follows its predecessor's reasons: {:?}",
            lines[2]
        );
    }

    #[test]
    fn path_affinity_discriminates_verb_siblings() {
        let mut fused = vec![
            ("pkg/cmd/release/create/create.go".to_string(), 10.0f32),
            ("pkg/cmd/release/list/list.go".to_string(), 9.0f32),
            ("pkg/cmd/release/shared/fetch.go".to_string(), 8.0f32),
        ];
        rerank_path_affinity(&mut fused, "added Order flag for release list command");
        assert_eq!(
            fused[0].0, "pkg/cmd/release/list/list.go",
            "the verb bigram must lift the right sibling: {fused:?}"
        );
        assert_eq!(
            fused[1].0, "pkg/cmd/release/create/create.go",
            "the wrong verb sibling keeps only its family evidence: {fused:?}"
        );
    }

    #[test]
    fn path_affinity_leaves_prose_queries_untouched() {
        let before = vec![
            ("models/scanresults.go".to_string(), 5.0f32),
            ("scanner/scan.go".to_string(), 4.0f32),
        ];
        let mut fused = before.clone();
        rerank_path_affinity(
            &mut fused,
            "please repair the broken behavior when scanning",
        );
        assert_eq!(
            fused, before,
            "prose without exact segment tokens must not move scores"
        );
    }

    #[test]
    fn path_affinity_weak_single_matches_stay_bounded() {
        let mut fused = vec![
            ("pkg/cmd/pr/create/create.go".to_string(), 10.0f32),
            ("pkg/cmd/pr/view/view.go".to_string(), 9.0f32),
        ];
        rerank_path_affinity(&mut fused, "the view output should include the number");
        assert_eq!(
            fused[0].0, "pkg/cmd/pr/create/create.go",
            "one isolated token must not overturn a real score gap: {fused:?}"
        );
    }

    #[test]
    fn fused_declaration_confident_prefix_caps_adaptive_widths_only() {
        let entry = |path: &str, score: f32| -> LocateFileEntry {
            serde_json::from_value(serde_json::json!({ "path": path, "score": score }))
                .expect("minimal file entry deserializes")
        };
        let wide = |n: usize| -> LocateResult {
            let mut result = LocateResult::default();
            result.files = (0..n)
                .map(|i| entry(&format!("f{i}.go"), (n - i) as f32))
                .collect();
            result
        };
        let mut adaptive = wide(12);
        bound_fused_declaration_to_primary(&mut adaptive, 12, true);
        assert_eq!(
            adaptive.files.len(),
            8,
            "adaptive declarations hold to the confident prefix"
        );
        let mut explicit = wide(12);
        bound_fused_declaration_to_primary(&mut explicit, 12, false);
        assert_eq!(
            explicit.files.len(),
            12,
            "explicit caller widths are honored as-is"
        );
        let mut narrow = wide(4);
        bound_fused_declaration_to_primary(&mut narrow, 4, true);
        assert_eq!(
            narrow.files.len(),
            4,
            "the prefix cap never widens a narrow budget"
        );
    }

    #[test]
    fn fuse_locate_results_is_deterministic() {
        let build = || {
            vec![
                fusion_result(vec![
                    fusion_entity("e1", "src/one.rs", 5.0),
                    fusion_entity("e2", "src/two.rs", 4.0),
                ]),
                fusion_result(vec![
                    fusion_entity("e2", "src/two.rs", 3.0),
                    fusion_entity("e3", "src/three.rs", 2.0),
                ]),
            ]
        };
        let variants = vec!["q0".to_string(), "q1".to_string()];
        let first = fuse_locate_results(variants.clone(), build(), 60.0);
        let second = fuse_locate_results(variants, build(), 60.0);
        let first_ids: Vec<&str> = first
            .entities
            .iter()
            .map(|e| e.entity_id.as_str())
            .collect();
        let second_ids: Vec<&str> = second
            .entities
            .iter()
            .map(|e| e.entity_id.as_str())
            .collect();
        assert_eq!(first_ids, second_ids);
    }

    /// The positive control: a query that NAMES a symbol classifies as a name
    /// hit, whichever pool surfaced it.
    #[test]
    fn a_query_that_names_a_symbol_is_a_name_match() {
        assert_eq!(
            classify_locate_match(
                "cross_encoder_model_cached",
                "cross_encoder_model_cached",
                "",
                None,
            ),
            LocateMatchKind::Name
        );
        // Case and surrounding prose do not change the verdict, and neither does
        // the seed pool: a name hit that also came through the vector arm is
        // still a name hit.
        assert_eq!(
            classify_locate_match(
                "where is Cross_Encoder_Model_Cached decided?",
                "cross_encoder_model_cached",
                "vector",
                Some(0.91),
            ),
            LocateMatchKind::Name
        );
        // A dotted name is named by its last segment, the same way the exact
        // name boost reads it.
        assert_eq!(
            classify_locate_match("call parse_request", "http.parse_request", "", None),
            LocateMatchKind::Name
        );
    }

    /// The negative control, which is the whole point of the field: a query for
    /// a symbol that exists nowhere still returns the retriever's best
    /// candidates, and every one of them must be flagged as a fallback.
    #[test]
    fn a_nonexistent_symbol_leaves_every_hit_flagged_as_fallback() {
        let absent = "kin_absent_symbol_negative_control";
        for (name, origin, cosine, expected) in [
            ("candidate", "", None, LocateMatchKind::TextFallback),
            (
                "query_trace_matches",
                "text",
                None,
                LocateMatchKind::TextFallback,
            ),
            (
                "exact_name_match",
                "vector",
                Some(0.81),
                LocateMatchKind::Semantic,
            ),
            (
                "cosine_only_match",
                "",
                Some(0.79),
                LocateMatchKind::Semantic,
            ),
        ] {
            assert_eq!(
                classify_locate_match(absent, name, origin, cosine),
                expected,
                "no token of {absent} names {name}"
            );
            assert_ne!(
                classify_locate_match(absent, name, origin, cosine),
                LocateMatchKind::Name
            );
        }
    }

    /// A shared substring is not a name. Without this the field would classify
    /// nearly everything as a name hit and answer nothing.
    #[test]
    fn a_merely_related_word_is_not_a_name_match() {
        assert_eq!(
            classify_locate_match(
                "Where does Kin decide whether to use the reranker?",
                "decide_review_with_graph",
                "",
                None,
            ),
            LocateMatchKind::TextFallback
        );
        assert!(!query_names_entity("encoder", "cross_encoder_model_cached"));
        assert!(!query_names_entity("", "anything"));
        assert!(!query_names_entity("anything", ""));
    }

    /// The FIR-3079 rows, and the fact this fix deliberately does NOT touch.
    ///
    /// Every pair here was measured on a fully embedded hiredis store (730
    /// entities, 1,485 of 1,485 indexed). The sentence "when I send a command,
    /// how does it reach the socket" ranked the Win32 compatibility macro
    /// `send` (sockcompat.h:90) first at score 180.0 and `socket`
    /// (sockcompat.h:82) second at 165.0, ahead of `redisFormatCommand`
    /// (hiredis.c:572) at 300.0. A longer reply-parsing question put `socket`
    /// at 55.0 above a row at 902.1, a 16x deficit winning on tier alone.
    ///
    /// The query DID contain the word, so `match_kind` still says `name` and
    /// this test asserts that it does. Three other producers are documented as
    /// unable to disagree with that field (`cosine_match_kind`,
    /// `match_evidence.name_match`, and `semloc_query_has_exact_token`, which
    /// delegates to [`query_names_entity`]), so demoting the FACT would put a
    /// fused row in contradiction with its own evidence object. Only the
    /// ordering changes.
    #[test]
    fn a_prose_sentence_does_not_let_an_english_word_win_the_name_tier() {
        for (query, name) in [
            (
                "when I send a command, how does it reach the socket",
                "send",
            ),
            (
                "when I send a command, how does it reach the socket",
                "socket",
            ),
            (
                "When a reply comes back from the Redis server, how does hiredis turn the bytes \
                 on the socket into the reply object my code gets, and what happens along the \
                 way if the reply is only half there?",
                "socket",
            ),
            (
                "What happens between a component asking for an update and that update appearing \
                 on screen? Walk me through the path.",
                "Resolved.component",
            ),
            (
                "What happens between a component asking for an update and that update appearing \
                 on screen? Walk me through the path.",
                "Component",
            ),
            (
                "When I type a character in the editor, how does it end up in the document? Walk \
                 me through the path.",
                "TextmateSnippet.walk",
            ),
            // The same VS Code question against a Rust store. Measured on a
            // ripgrep store, that one sentence collides on TWO ordinary words
            // and fills the entire top six with tier-1 hits, none of them an
            // answer: `Walk` (crates/ignore/src/walk.rs:1117, 461.3) and `walk`
            // (crates/ignore/src/lib.rs:64, 456.1) from "Walk me through", then
            // `End` (crates/printer/src/jsont.rs:65, 455.3),
            // `PreludeWriter::end` (crates/printer/src/standard.rs:1647, 455.0)
            // and `Match::end` (crates/matcher/src/lib.rs:100, 450.0) from "end
            // up in the document". `end` is an open-class word, which is why
            // the rule keys on the SHAPE OF THE QUERY and the shape of the
            // matching token, never on a list of colliding words.
            (
                "When I type a character in the editor, how does it end up in the document? Walk \
                 me through the path.",
                "Walk",
            ),
            (
                "When I type a character in the editor, how does it end up in the document? Walk \
                 me through the path.",
                "Match::end",
            ),
            (
                "When I type a character in the editor, how does it end up in the document? Walk \
                 me through the path.",
                "End",
            ),
        ] {
            // The precondition: the shipped predicate DOES call this a name.
            // Without it this test would pass on a query that never collided,
            // which is exactly the error it caught on its first run.
            assert!(
                query_names_entity(query, name),
                "control precondition: {name} is a shipped name hit for this query"
            );
            // The FACT is preserved, on purpose.
            assert_eq!(
                classify_locate_match(query, name, "", None),
                LocateMatchKind::Name,
                "the query did contain {name}, and match_kind reports facts"
            );
            // The RANKING judgment is what changed.
            let mut entity = mk_locate_entity(name, 1.0, true);
            entity.match_kind = Some(LocateMatchKind::Name);
            assert_eq!(
                locate_exact_name_tier(&entity, query),
                0,
                "{name} is an English word in a sentence, so it ranks on score"
            );
            assert!(name_match_is_prose_word_collision(query, name));
        }
    }

    /// FIR-3079's other half, which must not regress: a LOOKUP keeps its
    /// exact-name tier, whatever English word it is spelled with.
    ///
    /// The measurement says the tier is load-bearing on the same store.
    /// `redisReaderGetReply` typed alone scores 450.0 and must outrank
    /// `redisGetReplyFromReader` at 652.007; `send` typed alone scores 180.0 and
    /// must outrank `win32_send` at 291.2. Both are score inversions only the
    /// tier can win, so a rule that demoted them would undo FIR-2338 to fix
    /// FIR-3079.
    #[test]
    fn a_symbol_lookup_keeps_its_exact_name_tier() {
        for (query, name) in [
            // Single English word typed alone: still a lookup.
            ("send", "send"),
            ("socket", "socket"),
            ("walk", "Walk"),
            ("search", "search"),
            ("Component", "Component"),
            // Symbol-shaped lookups, bare and qualified.
            ("redisReaderGetReply", "redisReaderGetReply"),
            ("redisReader::redisReaderGetReply", "redisReaderGetReply"),
            ("SearchWorker::search", "SearchWorker::search"),
            ("Gitignore", "Gitignore"),
            // Prose that names a REAL symbol keeps the tier, because the token
            // that named it is symbol-shaped.
            (
                "When a reply comes back, how does redisReaderGetReply handle a partial reply",
                "redisReaderGetReply",
            ),
            (
                "where is Cross_Encoder_Model_Cached decided?",
                "cross_encoder_model_cached",
            ),
        ] {
            let mut entity = mk_locate_entity(name, 1.0, true);
            entity.match_kind = Some(LocateMatchKind::Name);
            assert_eq!(
                locate_exact_name_tier(&entity, query),
                1,
                "{query:?} is a lookup for {name}, or names it symbolically"
            );
            assert!(!name_match_is_prose_word_collision(query, name));
        }
    }

    /// The shape rule itself, pinned on the exact strings that motivated it.
    ///
    /// Separated from the ordering tests because the thresholds are the
    /// arguable part: a change to either constant shows up here as a specific
    /// query changing sides rather than as a ranking that quietly moved.
    #[test]
    fn the_prose_shape_rule_reads_the_queries_it_was_written_for() {
        for query in [
            "when I send a command, how does it reach the socket",
            "What happens between a component asking for an update and that update appearing on \
             screen? Walk me through the path.",
            "When ripgrep looks through a single file, what happens from reading the bytes to \
             printing a line that matched?",
            "where is prune_orphaned_vectors defined",
        ] {
            assert!(query_is_prose(query), "{query:?} is a sentence");
        }
        for query in [
            "send",
            "walk",
            "redisReaderGetReply",
            "redisReader::redisReaderGetReply",
            "SearchWorker::search",
            "call parse_request",
            // Four tokens but only one stopword: a symbol path, not prose.
            "http.parse_request.to.string",
            "",
        ] {
            assert!(!query_is_prose(query), "{query:?} is a lookup");
        }

        // Both thresholds from both sides, so an off-by-one in either constant
        // is visible as a named case rather than as a silently moved ranking.
        // Token floor: three stopwords still lose to a three-token query.
        assert!(!query_is_prose("is it the"), "3 tokens is under the floor");
        assert!(
            query_is_prose("is it the walk"),
            "4 tokens clears the floor"
        );
        // Stopword floor: four tokens with one stopword is a symbol path.
        assert!(
            !query_is_prose("walk the parse_request handler"),
            "1 stopword is under the floor"
        );
        assert!(
            query_is_prose("walk the parse_request in handler"),
            "2 stopwords clears the floor"
        );
    }

    /// The drift guard. [`query_names_entity_symbolically`] is a REFINEMENT of
    /// [`query_names_entity`], so it must never accept a pair the base rule
    /// rejects; if it did, a demotion decision would rest on a name match the
    /// rest of locate does not believe in.
    ///
    /// The two read one tokenizer ([`query_tokens`]) precisely so they cannot
    /// disagree, and this is what would notice if someone split them again.
    #[test]
    fn the_symbolic_name_rule_never_claims_a_name_the_base_rule_denies() {
        let mut symbolic_hits = 0usize;
        for query in [
            "send",
            "when I send a command, how does it reach the socket",
            "redisReaderGetReply",
            "redisReader::redisReaderGetReply",
            "how does redisReaderGetReply handle a partial reply from the server",
            "InMemoryGraph::prune_orphaned_vectors",
            "where is Cross_Encoder_Model_Cached decided?",
            "Walk me through it",
            "",
            "unrelated words entirely",
        ] {
            for name in [
                "send",
                "socket",
                "Walk",
                "redisReaderGetReply",
                "InMemoryGraph::prune_orphaned_vectors",
                "cross_encoder_model_cached",
                "http.parse_request",
                "",
            ] {
                if query_names_entity_symbolically(query, name) {
                    symbolic_hits += 1;
                    assert!(
                        query_names_entity(query, name),
                        "{query:?} names {name:?} symbolically but not at all"
                    );
                }
            }
        }
        // The positive control: without it every rejection would satisfy the
        // implication and this test could not fail.
        assert!(
            symbolic_hits >= 4,
            "the table must exercise the symbolic path, got {symbolic_hits} hits"
        );
    }

    /// The ordering consequence, measured: demoting the collision hands rank
    /// one to the higher-scoring row the tier was burying.
    ///
    /// On hiredis the sentence "when I send a command, how does it reach the
    /// socket" ranked `send` at 180.0 above `redisFormatCommand` at 300.0. Once
    /// `send` does not take the tier, both rows sit in it together and score
    /// decides, which is the whole ask.
    #[test]
    fn demoting_the_collision_hands_rank_one_back_to_the_higher_score() {
        let ranked = |query: &str| {
            let mut entities: Vec<(usize, LocateEntity)> =
                [("send", 180.0f32), ("redisFormatCommand", 300.0)]
                    .into_iter()
                    .enumerate()
                    .map(|(rank, (name, score))| {
                        let mut entity = mk_locate_entity(name, score, true);
                        entity.match_kind = Some(classify_locate_match(query, name, "", None));
                        (rank, entity)
                    })
                    .collect();
            order_locate_entities(&mut entities, query, |_| 0);
            entities
                .into_iter()
                .map(|(_, entity)| entity)
                .collect::<Vec<_>>()
        };
        let prose = ranked("when I send a command, how does it reach the socket");
        assert_eq!(
            prose[0].name, "redisFormatCommand",
            "score decides once the English-word collision leaves the name tier"
        );
        // The fact survives the demotion, which is the invariant the other lane
        // and both all_fallback predicates depend on.
        let demoted = prose.iter().find(|e| e.name == "send").unwrap();
        assert_eq!(
            demoted.match_kind,
            Some(LocateMatchKind::Name),
            "the row still reports that the query contained its name"
        );
        // The control that lets this fail: type the macro's name as a lookup
        // and the shipped tier must still hand it rank one over the 300.0 row.
        // FIR-2338 built that guarantee and this fix must not undo it.
        assert_eq!(ranked("send")[0].name, "send");
    }

    /// The fused arm asks the tier question PER VARIANT, so one prose variant
    /// cannot demote a hit an explicit symbol variant asked for by name.
    ///
    /// `match_kind` on a fused row is already the strongest kind any variant
    /// reported. The tier has to match that shape or the two halves of one row
    /// disagree: a caller who fans out "…prose…" plus "send" asked for `send`
    /// by name in one of their own variants, and must get it.
    #[test]
    fn fused_ranking_keeps_a_name_tier_any_variant_earned() {
        let with_kind = |name: &str, score: f32| {
            let mut entity = mk_locate_entity(name, score, true);
            entity.match_kind = Some(LocateMatchKind::Name);
            entity
        };
        let prose = "when I send a command, how does it reach the socket";
        let fallback = |name: &str, score: f32| {
            let mut entity = mk_locate_entity(name, score, true);
            entity.match_kind = Some(LocateMatchKind::TextFallback);
            entity
        };
        // Both cases fan out to TWO variants, because `fuse_locate_results`
        // returns the single result untouched when there are fewer than two.
        // A first draft used one variant and its assertion passed without the
        // fusion code running at all; the lookup control below is what caught
        // that, and it is why both cases here are two-variant.
        //
        // Below the tier the fused arm orders on RRF rank, not on entity score,
        // so a demoted collision does not get re-sorted by score the way the
        // per-query comparator sorts it. The fused arm's contribution is
        // narrower than that: a demoted row can no longer be lifted OVER a row
        // RRF ranked above it. Each variant's own ranking has already applied
        // the tier for its own text before fusion sees it.
        let second_prose = "how do I send a request and read the answer from the server";
        let list = || {
            fusion_result(vec![
                fallback("redisFormatCommand", 300.0),
                with_kind("send", 180.0),
            ])
        };
        // Prose in every variant: `send` is a collision under both, so it holds
        // no tier anywhere and RRF decides.
        let all_prose = fuse_locate_results(
            vec![prose.to_string(), second_prose.to_string()],
            vec![list(), list()],
            60.0,
        );
        assert_eq!(
            all_prose.entities[0].name, "redisFormatCommand",
            "a demoted collision cannot be lifted over the row RRF ranked above it"
        );
        // The control that proves the line above is about the TIER and not
        // about the input order: identical lists, identical RRF, one variant
        // swapped for a LOOKUP. `send` earns the tier in that variant and takes
        // rank one back. Without this, a rule that demoted on the joined text,
        // or one that demoted everything, would pass the assertion above and
        // still be wrong.
        let with_symbol_variant = fuse_locate_results(
            vec![prose.to_string(), "send".to_string()],
            vec![list(), list()],
            60.0,
        );
        assert_eq!(
            with_symbol_variant.entities[0].name, "send",
            "a variant that named the symbol outright keeps its tier"
        );
    }

    /// A method the graph stores under its owner is still named by the name it
    /// declares.
    ///
    /// The parsers qualify a Rust or C++ method as `Type::method`, so this is
    /// the shape of most entities in Kin's own graph. The query tokenizer splits
    /// on every non-identifier character, which is why NEITHER the bare name nor
    /// the fully qualified one used to be recognized: the tokens of
    /// `InMemoryGraph::prune_orphaned_vectors` are `inmemorygraph` and
    /// `prune_orphaned_vectors`, and neither equals the joined name.
    #[test]
    fn a_query_names_a_method_the_graph_stores_under_its_owner() {
        for query in [
            "prune_orphaned_vectors",
            "InMemoryGraph::prune_orphaned_vectors",
            "where is prune_orphaned_vectors defined",
        ] {
            assert!(
                query_names_entity(query, "InMemoryGraph::prune_orphaned_vectors"),
                "{query} names the method it names"
            );
        }
        // Every separator the parsers actually emit.
        assert!(query_names_entity("Variant", "Enum::Variant"));
        assert!(query_names_entity("method", "outer::Inner::method"));
        assert!(query_names_entity("Raspbian", "constant.Raspbian"));

        // The controls that let this check fail. Naming the OWNER is not naming
        // the member, an unrelated token is still not a name, and a trailing
        // separator leaves no tail that could match everything.
        assert!(!query_names_entity(
            "InMemoryGraph",
            "InMemoryGraph::prune_orphaned_vectors"
        ));
        assert!(!query_names_entity(
            "prune",
            "InMemoryGraph::prune_orphaned_vectors"
        ));
        assert!(!query_names_entity("vectors", "InMemoryGraph::prune"));
        assert!(!query_names_entity("anything", "Trailing::"));
    }

    /// The ranking half of the same fact: a bare exact symbol name is an EXACT
    /// name match against the qualified entity, not the zero that dropped it.
    ///
    /// `split_identifier_parts` does not treat `::` as a boundary, so the parts
    /// of the method below are `in`, `memory`, `graph::prune`, `orphaned`,
    /// `vectors`. A search for `prune_orphaned_vectors` matches two of its three
    /// parts, a compound partial is noise by this function's own rule, and the
    /// result was 0.0 for the one query shape a developer types most.
    #[test]
    fn a_bare_symbol_name_exactly_matches_its_qualified_entity() {
        assert_eq!(
            score_name_match(
                "prune_orphaned_vectors",
                "InMemoryGraph::prune_orphaned_vectors"
            ),
            5.0
        );
        assert_eq!(score_name_match("parse_request", "http.parse_request"), 5.0);
        // The unqualified verdict is unchanged, which is the point: this
        // restores the exact match qualification hid rather than widening it.
        assert_eq!(
            score_name_match("prune_orphaned_vectors", "prune_orphaned_vectors"),
            5.0
        );

        // Controls. Naming the owner matches nothing, a partial name stays a
        // partial, and an unrelated compound term stays noise.
        assert_eq!(
            score_name_match("InMemoryGraph", "InMemoryGraph::prune_orphaned_vectors"),
            0.0
        );
        assert_eq!(
            score_name_match("orphaned_vectors", "InMemoryGraph::prune_orphaned_vectors"),
            3.0
        );
        assert_eq!(
            score_name_match("quantity_input", "InMemoryGraph::prune_orphaned_vectors"),
            0.0
        );
    }

    /// The defect as the dogfood measured it, in the arithmetic that produced
    /// the number.
    ///
    /// `InMemoryGraph::prune_orphaned_vectors` scored 52.05 in `files[].symbols`
    /// on 0.5.17 and 52.054 on 0.5.21, the same value on two releases. It
    /// decomposes exactly: a name score of ZERO, one substring hit in the
    /// signature (0.5), times the 100 proximity weight, plus 2.0 for the
    /// function kind and 0.054 for a 54-line span. The name score being zero is
    /// the whole of it, and 52.054 is what a symbol ranked on its signature text
    /// alone is worth.
    #[test]
    fn the_exact_name_candidate_is_ranked_on_its_name_not_its_signature_text() {
        let mut entity = test_entity(
            "InMemoryGraph::prune_orphaned_vectors",
            "crates/kin-db/src/engine/graph.rs",
            5558,
            5612,
        );
        entity.signature = "fn prune_orphaned_vectors(&self) -> usize".to_string();
        let terms = vec!["prune_orphaned_vectors".to_string()];

        let ranked = rank_enriched_symbols(vec![entity.clone()], &terms, false, 8);
        assert_eq!(ranked.len(), 1);
        let scored_on_signature_alone: f32 = 0.5 * 100.0 + 2.0 + 0.054;
        assert!(
            (scored_on_signature_alone - 52.054).abs() < 0.001,
            "the recorded signature is what a zero name score composes to"
        );
        assert!(
            ranked[0].score > scored_on_signature_alone,
            "the exact-name candidate scored {} , which is the signature-text-only \
             value the dogfood recorded on 0.5.17 and 0.5.21",
            ranked[0].score
        );
        assert!(
            (ranked[0].score - (10.5 * 100.0 + 2.0 + 0.054)).abs() < 0.01,
            "an exact name match is worth 5.0, so proximity is 10.5 rather than 0.5"
        );

        // The control that lets this fail: an entity the query does not name
        // keeps the signature-only shape, so the assertion above is about the
        // name score and not about the composite being large for everything.
        let mut unrelated = test_entity(
            "InMemoryGraph::descriptor",
            "crates/kin-db/src/engine/graph.rs",
            10,
            64,
        );
        unrelated.signature = "fn descriptor(&self) -> Descriptor".to_string();
        let ranked_unrelated = rank_enriched_symbols(vec![unrelated], &terms, false, 8);
        assert_eq!(ranked_unrelated.len(), 1);
        assert!(
            ranked_unrelated[0].score < 10.0,
            "an entity the query never named must not be lifted by this change"
        );
    }

    /// The surface an agent reads, end to end: the exact-name symbol reaches
    /// `entities[]` LABELLED as a name hit, and the page stops declaring itself
    /// an all-fallback ranking.
    ///
    /// `all_fallback` is what the MCP honesty envelope reads to say "the query
    /// named a symbol and no ranked entity carries that name". With the
    /// qualified name unrecognized, that sentence was emitted about a page whose
    /// first row WAS the symbol, so the disclosure and the ranking contradicted
    /// each other on the same response.
    #[test]
    fn an_exact_name_hit_reaches_the_entity_surface_as_a_name_match() {
        let graph = kin_db::InMemoryGraph::new();
        let path = "crates/kin-db/src/engine/graph.rs";
        graph
            .upsert_entity(&test_entity(
                "InMemoryGraph::prune_orphaned_vectors",
                path,
                5558,
                5612,
            ))
            .unwrap();
        graph
            .upsert_entity(&test_entity("InMemoryGraph::descriptor", path, 10, 64))
            .unwrap();

        let symbol = |name: &str, span: [u32; 2], score: f32| LocateSymbol {
            name: name.to_string(),
            span: Some(span),
            score,
            kind: "method".to_string(),
            definition: true,
            origin: "text".to_string(),
            cosine: None,
            snippet: None,
        };
        let mut result = LocateResult {
            files: vec![LocateFileEntry {
                path: path.to_string(),
                score: 0.1909,
                signals: vec![],
                spans: vec![],
                symbols: vec![
                    symbol("InMemoryGraph::descriptor", [10, 64], 90.0),
                    symbol(
                        "InMemoryGraph::prune_orphaned_vectors",
                        [5558, 5612],
                        52.054,
                    ),
                ],
                explain: vec![],
                provenance: None,
                signal_scores: None,
                score_breakdown: None,
                matched_queries: Vec::new(),
            }],
            ..Default::default()
        };
        build_entity_view(
            &mut result,
            &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
            &SnippetOptions::enabled(None).without_bodies(),
            kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
            "prune_orphaned_vectors",
            false,
        )
        .unwrap();

        let named = result
            .entities
            .iter()
            .find(|entity| entity.name == "InMemoryGraph::prune_orphaned_vectors")
            .expect("the exact-name symbol must reach the entity surface");
        assert_eq!(
            named.match_kind,
            Some(LocateMatchKind::Name),
            "the query is this entity's name, so the row must say so"
        );
        assert!(
            !result.all_fallback,
            "a ranking holding the named symbol is not a ranking that named nothing"
        );

        // The control: the row the query did NOT name keeps its fallback label,
        // so the assertion above is about the name rule rather than about every
        // row being relabelled.
        let other = result
            .entities
            .iter()
            .find(|entity| entity.name == "InMemoryGraph::descriptor")
            .expect("the other symbol still ranks");
        assert_eq!(other.match_kind, Some(LocateMatchKind::TextFallback));
    }

    /// Entity projection must retain the path demotion that already shaped file
    /// ranking. The controls prove ordinary source is unchanged, tests stay
    /// demoted, and an explicitly named examples symbol is still a direct hit
    /// through the higher name tier.
    #[test]
    #[serial_test::serial]
    fn examples_entities_do_not_outrank_library_code_on_description_queries() {
        let _penalties =
            kin_core::test_env::EnvVarGuard::set("KIN_LOCATE_POST_TEST_PENALTY", "0.35")
                .with("KIN_LOCATE_POST_TEST_QUERY_PENALTY", "1.0")
                .with("KIN_LOCATE_DOCS_PATH_PENALTY", "0.01")
                .with("KIN_LOCATE_ENTITY_SURFACE_PENALTY", "0.3");
        let graph = kin_db::InMemoryGraph::new();
        let candidates = [
            ("example_handler", "examples/handler.rs", 0.99_f32),
            ("test_handler", "tests/handler.rs", 0.98_f32),
            ("production_handler", "lib/handler.rs", 0.90_f32),
        ];
        for (name, path, _) in candidates {
            graph
                .upsert_entity(&test_entity(name, path, 10, 20))
                .unwrap();
        }

        let rank = |query: &str| {
            let files = candidates
                .iter()
                .map(|(name, path, score)| LocateFileEntry {
                    path: (*path).to_string(),
                    score: *score,
                    signals: vec![],
                    spans: vec![],
                    symbols: vec![LocateSymbol {
                        name: (*name).to_string(),
                        span: Some([10, 20]),
                        score: *score,
                        kind: "function".to_string(),
                        definition: true,
                        origin: "text".to_string(),
                        cosine: None,
                        snippet: None,
                    }],
                    explain: vec![],
                    provenance: None,
                    signal_scores: None,
                    score_breakdown: None,
                    matched_queries: Vec::new(),
                })
                .collect();
            let mut result = LocateResult {
                files,
                ..Default::default()
            };
            build_entity_view(
                &mut result,
                &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
                &SnippetOptions::enabled(None).without_bodies(),
                kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
                query,
                false,
            )
            .unwrap();
            result.entities
        };

        let described = rank("where is a request handled");
        assert_eq!(
            described[0].name, "production_handler",
            "path-keyed examples and test demotions must survive entity projection: {described:?}"
        );
        let scores = described
            .iter()
            .map(|entity| (entity.name.as_str(), entity.score))
            .collect::<std::collections::HashMap<_, _>>();
        assert_eq!(scores["production_handler"], 0.90);
        assert!(scores["test_handler"] < scores["production_handler"]);
        assert!(scores["example_handler"] < scores["test_handler"]);

        let named = rank("example_handler");
        assert_eq!(
            named[0].name, "example_handler",
            "the name tier must keep a genuinely named examples symbol directly addressable"
        );
        assert_eq!(named[0].match_kind, Some(LocateMatchKind::Name));
    }

    /// FIR-2338, the per-query half, in the shape the flagship gauntlet
    /// measured on shipped 0.5.33: probe qf01 asked for
    /// `RepositoryAuthorityState::resolve_ref_target` by its exact qualified
    /// name, the match scored its fixed 460, and two `text_fallback` rows
    /// outbid it at 652.03 and 602.06 because the fallback scale is additive
    /// over lexical mass while exactness is a fixed product. 3,166 entities
    /// never expressed it; 26,633 did.
    ///
    /// The control is the scale sweep: the distractor's score grows without
    /// bound and the exact-name hit must hold rank 1 at EVERY magnitude,
    /// because the exact-name tier is consulted before the score. Under
    /// score-first ordering the first iteration already fails.
    #[test]
    fn an_exact_name_hit_cannot_be_outbid_by_text_fallback_at_any_scale() {
        let graph = kin_db::InMemoryGraph::new();
        let path = "crates/kin-db/src/storage/repository.rs";
        graph
            .upsert_entity(&test_entity(
                "RepositoryAuthorityState::resolve_ref_target",
                path,
                100,
                140,
            ))
            .unwrap();
        graph
            .upsert_entity(&test_entity(
                "repository_authority_state_contains_commit",
                path,
                200,
                260,
            ))
            .unwrap();
        let symbol = |name: &str, span: [u32; 2], score: f32| LocateSymbol {
            name: name.to_string(),
            span: Some(span),
            score,
            kind: "method".to_string(),
            definition: true,
            origin: "text".to_string(),
            cosine: None,
            snippet: None,
        };

        // 652.03 is the score the gauntlet measured; the larger magnitudes are
        // the "any corpus scale" claim made executable.
        for distractor_score in [652.03_f32, 1.0e6, 1.0e9] {
            let mut result = LocateResult {
                files: vec![LocateFileEntry {
                    path: path.to_string(),
                    score: 0.2,
                    signals: vec![],
                    spans: vec![],
                    symbols: vec![
                        symbol(
                            "repository_authority_state_contains_commit",
                            [200, 260],
                            distractor_score,
                        ),
                        symbol(
                            "RepositoryAuthorityState::resolve_ref_target",
                            [100, 140],
                            460.0,
                        ),
                    ],
                    explain: vec![],
                    provenance: None,
                    signal_scores: None,
                    score_breakdown: None,
                    matched_queries: Vec::new(),
                }],
                ..Default::default()
            };
            build_entity_view(
                &mut result,
                &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
                &SnippetOptions::enabled(None).without_bodies(),
                kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
                "RepositoryAuthorityState::resolve_ref_target",
                false,
            )
            .unwrap();
            assert_eq!(
                result.entities[0].name, "RepositoryAuthorityState::resolve_ref_target",
                "the exact qualified match must hold rank 1 against a fallback \
                 score of {distractor_score}"
            );
            assert_eq!(result.entities[0].match_kind, Some(LocateMatchKind::Name));
        }

        // Control: with no name hit in the ranking, fallback rows still order
        // by score, so the tier is about exactness rather than a reorder of
        // everything.
        let mut fallback_only = LocateResult {
            files: vec![LocateFileEntry {
                path: path.to_string(),
                score: 0.2,
                signals: vec![],
                spans: vec![],
                symbols: vec![
                    symbol(
                        "RepositoryAuthorityState::resolve_ref_target",
                        [100, 140],
                        460.0,
                    ),
                    symbol(
                        "repository_authority_state_contains_commit",
                        [200, 260],
                        652.03,
                    ),
                ],
                explain: vec![],
                provenance: None,
                signal_scores: None,
                score_breakdown: None,
                matched_queries: Vec::new(),
            }],
            ..Default::default()
        };
        build_entity_view(
            &mut fallback_only,
            &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
            &SnippetOptions::enabled(None).without_bodies(),
            kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
            "how are refs resolved against repository authority",
            false,
        )
        .unwrap();
        assert!(
            fallback_only
                .entities
                .iter()
                .all(|entity| entity.match_kind != Some(LocateMatchKind::Name)),
            "control precondition: this query names neither entity"
        );
        assert_eq!(
            fallback_only.entities[0].name, "repository_authority_state_contains_commit",
            "with no exact-name hit, score order is untouched"
        );
    }

    /// FIR-2338, the fusion half. RRF sums rank reciprocals per variant, so a
    /// lexical neighbor surfaced at rank 1 by EVERY variant out-sums an exact
    /// name hit one variant ranked first, and fusion hands rank 1 back to the
    /// row the per-variant tier just demoted. The carried record's match kind
    /// is the tier at this layer too.
    #[test]
    fn multiquery_fusion_keeps_the_exact_name_hit_above_fallback_rrf_mass() {
        let with_kind = |name: &str, kind| {
            let mut entity = mk_locate_entity(name, 1.0, true);
            entity.match_kind = Some(kind);
            entity
        };
        // "neighbor" leads both variant lists: RRF 2/(k+1). "exact" appears
        // only in the primary list at rank 2: RRF 1/(k+3). Score order and RRF
        // order both prefer the neighbor; only the tier can pick the name hit.
        let fused = fuse_locate_results(
            vec!["q0".to_string(), "q1".to_string()],
            vec![
                fusion_result(vec![
                    with_kind("neighbor", LocateMatchKind::TextFallback),
                    with_kind("filler", LocateMatchKind::TextFallback),
                    with_kind("exact", LocateMatchKind::Name),
                ]),
                fusion_result(vec![
                    with_kind("neighbor", LocateMatchKind::TextFallback),
                    with_kind("filler", LocateMatchKind::TextFallback),
                ]),
            ],
            60.0,
        );
        assert_eq!(
            fused.entities[0].name, "exact",
            "the name hit must lead the fused ranking over fallback RRF mass"
        );
        // Control: among fallback rows RRF still decides, so the tier did not
        // flatten the fused ordering.
        let neighbor_pos = fused
            .entities
            .iter()
            .position(|entity| entity.name == "neighbor")
            .unwrap();
        let filler_pos = fused
            .entities
            .iter()
            .position(|entity| entity.name == "filler")
            .unwrap();
        assert!(
            neighbor_pos < filler_pos,
            "fallback rows keep their RRF order below the name tier"
        );
    }

    /// FIR-2337 in the shape the flagship gauntlet measured on shipped 0.5.33:
    /// probe qb11 `delete_work_item` returned four entities all carrying the
    /// exact name, all `match_kind: name`, all scored exactly 450.000, and the
    /// file-order tie-break put the canonical `InMemoryGraph::` definition
    /// FOURTH, behind two test doubles and a blanket `&G::` forwarding impl.
    ///
    /// The tie is broken by owner graph mass: the definition on the type that
    /// carries the most structural graph relations wins, mirroring the store
    /// (InMemoryGraph 285, MockGraph 134, EmptyStore 121, `&G` ownerless 0).
    /// The control run drops the owner edges so every mass is 0: the ordering
    /// must then fall back to exactly the file-order tie that shipped, proving
    /// this test moves on the tiebreak signal and nothing else.
    #[test]
    fn a_pure_exact_name_tie_breaks_toward_the_owner_with_graph_mass() {
        let relation = |kind: RelationKind, src: EntityId, dst: EntityId| Relation {
            id: RelationId::new(),
            kind,
            src: kin_model::GraphNodeId::Entity(src),
            dst: kin_model::GraphNodeId::Entity(dst),
            confidence: 1.0,
            origin: RelationOrigin::Parsed,
            created_in: None,
            import_source: None,
            evidence: Vec::new(),
        };
        // File order mirrors the shipped defect: the canonical definition's
        // file ranks LAST among the four.
        let impls: [(&str, &str); 4] = [
            (
                "MockGraph::delete_work_item",
                "crates/kin-git/src/export.rs",
            ),
            ("&G::delete_work_item", "kin-model/src/graph.rs"),
            (
                "EmptyStore::delete_work_item",
                "crates/kin-mcp/src/handlers/mod.rs",
            ),
            (
                "InMemoryGraph::delete_work_item",
                "crates/kin-db/src/engine/graph.rs",
            ),
        ];
        // Owner mass per impl, `&G` staying ownerless like the real blanket
        // forwarding impl. Peer entities give each owner its relation count.
        let owner_mass: [usize; 4] = [3, 0, 2, 5];

        let build = |with_owner_edges: bool| {
            let graph = kin_db::InMemoryGraph::new();
            let mut files = Vec::new();
            for ((name, path), mass) in impls.iter().zip(owner_mass) {
                let method = test_entity(name, path, 100, 140);
                graph.upsert_entity(&method).unwrap();
                if with_owner_edges && mass > 0 {
                    let owner = test_entity(name.split("::").next().unwrap(), path, 10, 400);
                    graph.upsert_entity(&owner).unwrap();
                    graph
                        .upsert_relation(&relation(RelationKind::Contains, owner.id, method.id))
                        .unwrap();
                    for _ in 1..mass {
                        let peer = test_entity("peer_helper", path, 500, 510);
                        graph.upsert_entity(&peer).unwrap();
                        graph
                            .upsert_relation(&relation(RelationKind::Calls, owner.id, peer.id))
                            .unwrap();
                    }
                }
                files.push(LocateFileEntry {
                    path: path.to_string(),
                    score: 0.2,
                    signals: vec![],
                    spans: vec![],
                    symbols: vec![LocateSymbol {
                        name: name.to_string(),
                        span: Some([100, 140]),
                        score: 450.0,
                        kind: "method".to_string(),
                        definition: true,
                        origin: "text".to_string(),
                        cosine: None,
                        snippet: None,
                    }],
                    explain: vec![],
                    provenance: None,
                    signal_scores: None,
                    score_breakdown: None,
                    matched_queries: Vec::new(),
                });
            }
            let mut result = LocateResult {
                files,
                ..Default::default()
            };
            build_entity_view(
                &mut result,
                &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
                &SnippetOptions::enabled(None).without_bodies(),
                kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
                "delete_work_item",
                false,
            )
            .unwrap();
            result
        };

        let fixed = build(true);
        let names: Vec<&str> = fixed
            .entities
            .iter()
            .map(|entity| entity.name.as_str())
            .collect();
        assert_eq!(
            names,
            vec![
                "InMemoryGraph::delete_work_item",
                "MockGraph::delete_work_item",
                "EmptyStore::delete_work_item",
                "&G::delete_work_item",
            ],
            "a pure exact-name tie must order by owner graph mass"
        );
        assert!(
            fixed.entities[0]
                .provenance
                .origin
                .contains("tie_break=owner_graph_mass:"),
            "the tie-break must be visible in the explain origin, got {:?}",
            fixed.entities[0].provenance.origin
        );

        // Control: no owner edges means no mass signal, and the ordering falls
        // back to the file-order tie that shipped the defect.
        let flat = build(false);
        let flat_names: Vec<&str> = flat
            .entities
            .iter()
            .map(|entity| entity.name.as_str())
            .collect();
        assert_eq!(
            flat_names,
            vec![
                "MockGraph::delete_work_item",
                "&G::delete_work_item",
                "EmptyStore::delete_work_item",
                "InMemoryGraph::delete_work_item",
            ],
            "with every owner mass equal the file-order tie-break is unchanged"
        );
        assert!(
            flat.entities[0]
                .provenance
                .origin
                .contains("tie_break=owner_graph_mass:0"),
            "an unbroken tie still discloses the signal it consulted, got {:?}",
            flat.entities[0].provenance.origin
        );
    }

    /// FIR-3079, the measured shape as a fixture: locate ranks the right FILE
    /// first and the entity surface carries nothing from it, because the
    /// surface is a projection of the symbols a query token happened to name.
    ///
    /// On React the file holding `scheduleUpdateOnFiber`, `performWorkOnRoot`
    /// and `commitRoot` ranked FIRST for "what happens between a component
    /// asking for an update and that update appearing on screen" and put one
    /// row at rank 97 of 136. Here the same shape is two files: the right one
    /// ranks first and its symbols are a helper nobody asked for, while a lower
    /// file carries a high-scoring lexical row. Rank one must become the top
    /// file's anchor.
    #[test]
    fn a_prose_question_gets_the_top_ranked_files_own_anchor() {
        let relation = |kind: RelationKind, src: EntityId, dst: EntityId| Relation {
            id: RelationId::new(),
            kind,
            src: kin_model::GraphNodeId::Entity(src),
            dst: kin_model::GraphNodeId::Entity(dst),
            confidence: 1.0,
            origin: RelationOrigin::Parsed,
            created_in: None,
            import_source: None,
            evidence: Vec::new(),
        };
        let file = |path: &str, score: f32, symbols: Vec<LocateSymbol>| LocateFileEntry {
            path: path.to_string(),
            score,
            signals: vec![],
            spans: vec![],
            symbols,
            explain: vec![],
            provenance: None,
            signal_scores: None,
            score_breakdown: None,
            matched_queries: Vec::new(),
        };
        let symbol = |name: &str, score: f32| LocateSymbol {
            name: name.to_string(),
            span: Some([10, 20]),
            score,
            kind: "function".to_string(),
            definition: true,
            origin: "text".to_string(),
            cosine: None,
            snippet: None,
        };
        let graph = kin_db::InMemoryGraph::new();

        // The right file. Its anchor is what the rest of the repository calls;
        // the symbol the retrieval resolved on it is a helper.
        let anchor = test_entity(
            "scheduleUpdateOnFiber",
            "packages/react-reconciler/src/ReactFiberWorkLoop.js",
            900,
            980,
        );
        graph.upsert_entity(&anchor).unwrap();
        for _ in 0..9 {
            let caller = test_entity(
                "caller",
                "packages/react-reconciler/src/ReactFiberHooks.js",
                1,
                2,
            );
            graph.upsert_entity(&caller).unwrap();
            graph
                .upsert_relation(&relation(RelationKind::Calls, caller.id, anchor.id))
                .unwrap();
        }
        let helper = test_entity(
            "shouldRemainOnPreviousScreen",
            "packages/react-reconciler/src/ReactFiberWorkLoop.js",
            10,
            20,
        );
        graph.upsert_entity(&helper).unwrap();

        // The lower file, carrying the kind of high-scoring lexical row that
        // takes the page today.
        let lexical = test_entity(
            "updateDehydratedSuspenseComponent",
            "packages/react-reconciler/src/ReactFiberBeginWork.js",
            10,
            20,
        );
        graph.upsert_entity(&lexical).unwrap();
        // The second file has an anchor of its own, so the decay is pinned: it
        // must sort below the first file's anchor even though its mass is
        // higher. Without a decay the file arm's order would be lost here.
        let second_anchor = test_entity(
            "beginWork",
            "packages/react-reconciler/src/ReactFiberBeginWork.js",
            100,
            400,
        );
        graph.upsert_entity(&second_anchor).unwrap();
        for _ in 0..30 {
            let caller = test_entity(
                "beginWorkCaller",
                "packages/react-reconciler/src/ReactFiberHooks.js",
                1,
                2,
            );
            graph.upsert_entity(&caller).unwrap();
            graph
                .upsert_relation(&relation(RelationKind::Calls, caller.id, second_anchor.id))
                .unwrap();
        }

        let question = "what happens between a component asking for an update \
                        and that update appearing on screen";
        let build = |anchors: &str| {
            let _guard = kin_core::test_env::EnvVarGuard::set("KIN_LOCATE_FILE_ANCHORS", anchors);
            let mut result = LocateResult {
                files: vec![
                    file(
                        "packages/react-reconciler/src/ReactFiberWorkLoop.js",
                        0.14,
                        vec![symbol("shouldRemainOnPreviousScreen", 95.7)],
                    ),
                    file(
                        "packages/react-reconciler/src/ReactFiberBeginWork.js",
                        0.13,
                        vec![symbol("updateDehydratedSuspenseComponent", 852.2)],
                    ),
                ],
                ..Default::default()
            };
            build_entity_view(
                &mut result,
                &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
                &SnippetOptions::enabled(None).without_bodies(),
                kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
                question,
                false,
            )
            .unwrap();
            result
        };

        // Control first: this is the defect, and the test cannot pass by
        // accident on a fixture where the anchor was already reachable.
        let shipped = build("0");
        let shipped_names: Vec<&str> = shipped
            .entities
            .iter()
            .map(|entity| entity.name.as_str())
            .collect();
        assert_eq!(
            shipped_names,
            vec![
                "updateDehydratedSuspenseComponent",
                "shouldRemainOnPreviousScreen"
            ],
            "control: without anchors the right file contributes only its helper"
        );

        let fixed = build("1");
        let names: Vec<&str> = fixed
            .entities
            .iter()
            .map(|entity| entity.name.as_str())
            .collect();
        assert_eq!(
            names,
            vec![
                "updateDehydratedSuspenseComponent",
                "scheduleUpdateOnFiber",
                "beginWork",
                "shouldRemainOnPreviousScreen"
            ],
            "the anchor of the FIRST file is admitted beneath the row retrieval \
             scored, above the second file's anchor, got {:?}",
            fixed
                .entities
                .iter()
                .map(|e| (&e.name, e.score))
                .collect::<Vec<_>>()
        );
        assert_ne!(
            fixed.entities[0].provenance.origin, FILE_ANCHOR_ORIGIN,
            "an anchor never takes rank one from a row that carries evidence"
        );
        assert_eq!(
            fixed.entities[1].provenance.origin, FILE_ANCHOR_ORIGIN,
            "and an anchor row says on the surface why it is there"
        );
        assert!(
            fixed.entities[1].score < fixed.entities[0].score,
            "the share is strictly below the ranking's own top score"
        );
        assert!(
            fixed.entities[1].score > fixed.entities[2].score,
            "and the decay separates the two anchors rather than tying them: {} vs {}",
            fixed.entities[1].score,
            fixed.entities[2].score
        );
    }

    /// A query that IS an identifier must be answered exactly as it was before
    /// anchors existed. The control is the same fixture under a question, which
    /// must differ: a rule that admitted nothing anywhere would pass the first
    /// assertion alone.
    #[test]
    fn a_symbol_lookup_ranking_is_byte_identical_with_anchors_on() {
        let file = |path: &str, symbols: Vec<LocateSymbol>| LocateFileEntry {
            path: path.to_string(),
            score: 0.2,
            signals: vec![],
            spans: vec![],
            symbols,
            explain: vec![],
            provenance: None,
            signal_scores: None,
            score_breakdown: None,
            matched_queries: Vec::new(),
        };
        let graph = kin_db::InMemoryGraph::new();
        let mut widget = test_entity(
            "CodeEditorWidget",
            "src/vs/editor/browser/widget/codeEditorWidget.ts",
            60,
            900,
        );
        widget.kind = EntityKind::Class;
        graph.upsert_entity(&widget).unwrap();
        let other = test_entity(
            "createTextModel",
            "src/vs/editor/browser/widget/codeEditorWidget.ts",
            10,
            20,
        );
        graph.upsert_entity(&other).unwrap();

        let build = |query: &str, anchors: &str| {
            let _guard = kin_core::test_env::EnvVarGuard::set("KIN_LOCATE_FILE_ANCHORS", anchors);
            let mut result = LocateResult {
                files: vec![file(
                    "src/vs/editor/browser/widget/codeEditorWidget.ts",
                    vec![LocateSymbol {
                        name: "createTextModel".to_string(),
                        span: Some([10, 20]),
                        score: 450.0,
                        kind: "function".to_string(),
                        definition: true,
                        origin: "text".to_string(),
                        cosine: None,
                        snippet: None,
                    }],
                )],
                ..Default::default()
            };
            build_entity_view(
                &mut result,
                &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
                &SnippetOptions::enabled(None).without_bodies(),
                kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
                query,
                false,
            )
            .unwrap();
            result
                .entities
                .iter()
                .map(|entity| entity.name.clone())
                .collect::<Vec<_>>()
        };

        assert_eq!(
            build("createTextModel", "1"),
            build("createTextModel", "0"),
            "a lookup is answered exactly as before"
        );
        assert_ne!(
            build(
                "how does a typed character reach the model behind the editor",
                "1"
            ),
            build(
                "how does a typed character reach the model behind the editor",
                "0"
            ),
            "control: the same fixture under a question must differ, or the \
             lookup assertion above proves nothing"
        );
    }

    /// The lookup gate is the negation of kin#1367's `query_is_prose`, and this
    /// pins both of its floors from both sides. An off-by-one in either constant
    /// shows up here as a named case rather than as a ranking that quietly moved.
    #[test]
    fn the_lookup_shape_rule_reads_both_of_its_floors() {
        // Every control the ranking lane holds byte-identical is a lookup here.
        for control in [
            "redisReaderGetReply",
            "redisFormatCommand",
            "send",
            "socket",
            "redisReader::redisReaderGetReply",
            "Gitignore",
            "SearchWorker::search",
            "WalkParallel",
            "walk",
            "search",
            "end",
            "Match::end",
            "TextModel",
            "CodeEditorWidget",
        ] {
            assert!(
                locate_query_is_symbol_lookup(control),
                "{control} must be answered as a lookup"
            );
        }
        // The token floor, both sides. Three words is the longest symbol path
        // the tokenizer produces.
        assert!(locate_query_is_symbol_lookup("is it the"));
        assert!(!locate_query_is_symbol_lookup("is it the walk"));
        // The stopword floor, both sides.
        assert!(locate_query_is_symbol_lookup(
            "walk the parse_request handler"
        ));
        assert!(!locate_query_is_symbol_lookup(
            "walk the parse_request in handler"
        ));
        // A question that NAMES an identifier is still prose, so anchors are
        // admitted beneath it; the exact-name tier is what keeps the named hit
        // at rank one, and that rule lives in kin#1367 rather than here.
        assert!(!locate_query_is_symbol_lookup(
            "where is prune_orphaned_vectors decided in this repository"
        ));
        // The measured questions, all prose.
        assert!(!locate_query_is_symbol_lookup(
            "When I type a character in the editor, how does it end up in the \
             document? Walk me through the path."
        ));
        assert!(!locate_query_is_symbol_lookup(
            "How does ripgrep decide which files to look at, and how does it \
             honour the ignore rules a project sets?"
        ));
    }

    /// A method's anchor is its owning type. Without the kind rule a
    /// widely-called method takes both anchor slots its file has, which is the
    /// same failure by another route: the surface fills with one type's
    /// internals and never names the type.
    #[test]
    fn a_widely_called_method_never_takes_an_anchor_slot() {
        let relation = |kind: RelationKind, src: EntityId, dst: EntityId| Relation {
            id: RelationId::new(),
            kind,
            src: kin_model::GraphNodeId::Entity(src),
            dst: kin_model::GraphNodeId::Entity(dst),
            confidence: 1.0,
            origin: RelationOrigin::Parsed,
            created_in: None,
            import_source: None,
            evidence: Vec::new(),
        };
        let graph = kin_db::InMemoryGraph::new();
        let path = "src/vs/editor/browser/widget/codeEditorWidget.ts";
        let mut method = test_entity("CodeEditorWidget.trigger", path, 700, 760);
        method.kind = EntityKind::Method;
        graph.upsert_entity(&method).unwrap();
        for _ in 0..40 {
            let caller = test_entity(
                "caller",
                "src/vs/editor/contrib/find/findController.ts",
                1,
                2,
            );
            graph.upsert_entity(&caller).unwrap();
            graph
                .upsert_relation(&relation(RelationKind::Calls, caller.id, method.id))
                .unwrap();
        }
        let mut widget = test_entity("CodeEditorWidget", path, 60, 900);
        widget.kind = EntityKind::Class;
        graph.upsert_entity(&widget).unwrap();

        let mut result = LocateResult {
            files: vec![LocateFileEntry {
                path: path.to_string(),
                score: 0.25,
                signals: vec![],
                spans: vec![],
                symbols: vec![],
                explain: vec![],
                provenance: None,
                signal_scores: None,
                score_breakdown: None,
                matched_queries: Vec::new(),
            }],
            ..Default::default()
        };
        build_entity_view(
            &mut result,
            &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
            &SnippetOptions::enabled(None).without_bodies(),
            kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
            "how does a typed character reach the model behind the editor",
            false,
        )
        .unwrap();
        let names: Vec<&str> = result
            .entities
            .iter()
            .map(|entity| entity.name.as_str())
            .collect();
        assert_eq!(
            names,
            vec!["CodeEditorWidget"],
            "the class is the anchor even though the method carries forty times its mass"
        );
    }

    /// The decay is the protection, and it is measured: on ripgrep the file
    /// holding `Walk` ranked FIFTH while rank one was a genuinely right answer
    /// the query named. An anchor from a fifth-ranked file must not take that
    /// rank away.
    #[test]
    fn an_anchor_from_a_low_ranked_file_does_not_outrank_a_named_hit() {
        let relation = |kind: RelationKind, src: EntityId, dst: EntityId| Relation {
            id: RelationId::new(),
            kind,
            src: kin_model::GraphNodeId::Entity(src),
            dst: kin_model::GraphNodeId::Entity(dst),
            confidence: 1.0,
            origin: RelationOrigin::Parsed,
            created_in: None,
            import_source: None,
            evidence: Vec::new(),
        };
        let graph = kin_db::InMemoryGraph::new();
        let named = test_entity("WalkBuilder::ignore", "crates/ignore/src/walk.rs", 890, 900);
        graph.upsert_entity(&named).unwrap();
        // The measured neighbourhood, and it is load-bearing since the
        // corroboration rule landed: on the real store walk.rs contributes two
        // more rows the retriever scored on their own, which is what keeps this
        // collision at its full 1052. A fixture with the lone symbol would
        // demote it to 789 and let this file's own anchor pass it.
        for (sibling, lo, hi) in [
            ("WalkBuilder::add_ignore", 910u32, 930u32),
            ("WalkBuilder::add_custom_ignore_filename", 940, 960),
        ] {
            let entity = test_entity(sibling, "crates/ignore/src/walk.rs", lo, hi);
            graph.upsert_entity(&entity).unwrap();
        }
        let mut deep = test_entity("Walk", "crates/ignore/src/walk.rs", 1117, 1200);
        deep.kind = EntityKind::Class;
        graph.upsert_entity(&deep).unwrap();
        for _ in 0..60 {
            let caller = test_entity("caller", "crates/core/search.rs", 1, 2);
            graph.upsert_entity(&caller).unwrap();
            graph
                .upsert_relation(&relation(RelationKind::Calls, caller.id, deep.id))
                .unwrap();
        }

        let spacer = |path: &str, score: f32| LocateFileEntry {
            path: path.to_string(),
            score,
            signals: vec![],
            spans: vec![],
            symbols: vec![],
            explain: vec![],
            provenance: None,
            signal_scores: None,
            score_breakdown: None,
            matched_queries: Vec::new(),
        };
        // File order is the measured one: walk.rs ranked FIFTH and still
        // produced the entity ranking's rank one, so the anchor decay is what
        // has to protect it. At rank five that anchor scores 300 against the
        // named hit's 1052, which is a score decision and not a tier one, so
        // this stays true whatever the exact-name tier is later ruled to do.
        let mut result = LocateResult {
            files: vec![
                spacer("crates/regex/src/literal.rs", 0.231),
                spacer("crates/core/flags/defs.rs", 0.227),
                spacer("crates/ignore/src/incremental.rs", 0.226),
                spacer("crates/ignore/src/dir.rs", 0.226),
                LocateFileEntry {
                    path: "crates/ignore/src/walk.rs".to_string(),
                    score: 0.223,
                    signals: vec![],
                    spans: vec![],
                    symbols: vec![
                        LocateSymbol {
                            name: "WalkBuilder::ignore".to_string(),
                            span: Some([890, 900]),
                            score: 1052.0,
                            kind: "method".to_string(),
                            definition: true,
                            origin: "text".to_string(),
                            cosine: None,
                            snippet: None,
                        },
                        LocateSymbol {
                            name: "WalkBuilder::add_ignore".to_string(),
                            span: Some([910, 930]),
                            score: 652.0,
                            kind: "method".to_string(),
                            definition: true,
                            origin: "text".to_string(),
                            cosine: None,
                            snippet: None,
                        },
                        LocateSymbol {
                            name: "WalkBuilder::add_custom_ignore_filename".to_string(),
                            span: Some([940, 960]),
                            score: 652.0,
                            kind: "method".to_string(),
                            definition: true,
                            origin: "text".to_string(),
                            cosine: None,
                            snippet: None,
                        },
                    ],
                    explain: vec![],
                    provenance: None,
                    signal_scores: None,
                    score_breakdown: None,
                    matched_queries: Vec::new(),
                },
            ],
            ..Default::default()
        };
        build_entity_view(
            &mut result,
            &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
            &SnippetOptions::enabled(None).without_bodies(),
            kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
            "how does ripgrep decide which files to look at and honour the ignore rules",
            false,
        )
        .unwrap();
        assert_eq!(
            result.entities[0].name,
            "WalkBuilder::ignore",
            "a hit the query named keeps rank one, got {:?}",
            result
                .entities
                .iter()
                .map(|e| (&e.name, e.score))
                .collect::<Vec<_>>()
        );
        let walk = result
            .entities
            .iter()
            .find(|entity| entity.name == "Walk")
            .expect("the anchor the question was actually about is now on the page");
        assert_eq!(walk.provenance.origin, FILE_ANCHOR_ORIGIN);
        assert!(
            walk.score < result.entities[0].score,
            "and it is admitted beneath the evidence, not above it: {} vs {}",
            walk.score,
            result.entities[0].score
        );
    }

    /// One ranked file for the corroboration fixtures.
    fn corroboration_file(path: &str, score: f32, symbols: Vec<LocateSymbol>) -> LocateFileEntry {
        LocateFileEntry {
            path: path.to_string(),
            score,
            signals: vec![],
            spans: vec![],
            symbols,
            explain: vec![],
            provenance: None,
            signal_scores: None,
            score_breakdown: None,
            matched_queries: Vec::new(),
        }
    }

    /// One projected symbol for the corroboration fixtures.
    fn corroboration_symbol(name: &str, score: f32, span: [u32; 2]) -> LocateSymbol {
        LocateSymbol {
            name: name.to_string(),
            span: Some(span),
            score,
            kind: "function".to_string(),
            definition: true,
            origin: "text".to_string(),
            cosine: None,
            snippet: None,
        }
    }

    /// FIR-3079, the React shape: a prose-word collision leads on raw score after
    /// kin#1367 demotes it out of the name tier, and it is the ONLY row its file
    /// contributes to the whole ranking. Measured at 1052.0 against a best
    /// non-colliding 852.3.
    ///
    /// Every file here carries exactly one entity, so the file-anchor admission
    /// finds nothing new and this test measures the corroboration rule alone.
    #[test]
    fn a_lexical_accident_alone_in_its_file_loses_the_page_lead() {
        let graph = kin_db::InMemoryGraph::new();
        let lone = test_entity(
            "Resolved.component",
            "compiler/packages/babel-plugin-react-compiler/src/Flood/Types.ts",
            10,
            20,
        );
        graph.upsert_entity(&lone).unwrap();
        let clean = test_entity(
            "attemptEarlyBailoutIfNoScheduledUpdate",
            "packages/react-reconciler/src/ReactFiberBeginWork.js",
            30,
            60,
        );
        graph.upsert_entity(&clean).unwrap();

        let question = "what happens between a component asking for an update \
                        and that update appearing on screen";
        let build = |on: &str| {
            let _guard =
                kin_core::test_env::EnvVarGuard::set("KIN_LOCATE_COLLISION_CORROBORATION", on);
            let mut result = LocateResult {
                files: vec![
                    corroboration_file(
                        "compiler/packages/babel-plugin-react-compiler/src/Flood/Types.ts",
                        0.14,
                        vec![corroboration_symbol("Resolved.component", 1052.0, [10, 20])],
                    ),
                    corroboration_file(
                        "packages/react-reconciler/src/ReactFiberBeginWork.js",
                        0.13,
                        vec![corroboration_symbol(
                            "attemptEarlyBailoutIfNoScheduledUpdate",
                            852.3,
                            [30, 60],
                        )],
                    ),
                ],
                ..Default::default()
            };
            build_entity_view(
                &mut result,
                &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
                &SnippetOptions::enabled(None).without_bodies(),
                kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
                question,
                false,
            )
            .unwrap();
            result
        };

        // Control: this is the shipped ranking, and the whole point is that the
        // collision leads it on score alone.
        let shipped = build("0");
        assert_eq!(
            shipped.entities[0].name, "Resolved.component",
            "control: without the rule the accident still leads on raw score"
        );
        assert_eq!(shipped.entities[0].match_kind, Some(LocateMatchKind::Name));

        let fixed = build("1");
        assert_eq!(
            fixed.entities[0].name,
            "attemptEarlyBailoutIfNoScheduledUpdate",
            "the uncorroborated accident loses the lead, got {:?}",
            fixed
                .entities
                .iter()
                .map(|e| (&e.name, e.score))
                .collect::<Vec<_>>()
        );
        let demoted = fixed
            .entities
            .iter()
            .find(|e| e.name == "Resolved.component")
            .expect("a share is not a floor: the row is still ranked");
        assert_eq!(
            demoted.match_kind,
            Some(LocateMatchKind::Name),
            "the demotion moves the score and never the fact"
        );
        assert!(
            (demoted.score - 789.0).abs() < 1.0,
            "three quarters of 1052, got {}",
            demoted.score
        );
    }

    /// The ripgrep shape, and the case the rule exists to SPARE: the same score,
    /// the same match kind, a collision on an ordinary word, and a right answer.
    /// Its file contributes two more rows the retriever scored on their own.
    #[test]
    fn a_collision_its_own_file_corroborates_keeps_rank_one() {
        let graph = kin_db::InMemoryGraph::new();
        for (name, lo, hi) in [
            ("WalkBuilder::ignore", 890u32, 900u32),
            ("WalkBuilder::add_ignore", 910, 930),
            ("WalkBuilder::add_custom_ignore_filename", 940, 960),
        ] {
            let entity = test_entity(name, "crates/ignore/src/walk.rs", lo, hi);
            graph.upsert_entity(&entity).unwrap();
        }
        let other = test_entity("ignore_messages", "crates/core/messages.rs", 10, 20);
        graph.upsert_entity(&other).unwrap();

        let mut result = LocateResult {
            files: vec![
                corroboration_file(
                    "crates/ignore/src/walk.rs",
                    0.223,
                    vec![
                        corroboration_symbol("WalkBuilder::ignore", 1052.0, [890, 900]),
                        corroboration_symbol("WalkBuilder::add_ignore", 652.0, [910, 930]),
                        corroboration_symbol(
                            "WalkBuilder::add_custom_ignore_filename",
                            652.0,
                            [940, 960],
                        ),
                    ],
                ),
                corroboration_file(
                    "crates/core/messages.rs",
                    0.133,
                    vec![corroboration_symbol("ignore_messages", 652.0, [10, 20])],
                ),
            ],
            ..Default::default()
        };
        build_entity_view(
            &mut result,
            &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
            &SnippetOptions::enabled(None).without_bodies(),
            kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
            "how does ripgrep decide which files to look at and honour the ignore rules",
            false,
        )
        .unwrap();
        assert_eq!(
            result.entities[0].name,
            "WalkBuilder::ignore",
            "a collision its file corroborates keeps rank one, got {:?}",
            result
                .entities
                .iter()
                .map(|e| (&e.name, e.score))
                .collect::<Vec<_>>()
        );
        assert!(
            (result.entities[0].score - 1052.0).abs() < 0.01,
            "and keeps its whole score, got {}",
            result.entities[0].score
        );
    }

    /// The rule's own failure mode, measured rather than argued: a RIGHT answer
    /// that is the only row its file contributes, whose name is an ordinary word
    /// the question used, is demoted for being alone.
    ///
    /// The demotion is a share of the score and never a floor, so the row ranks
    /// lower and stays on the page an agent reads. That is the claim this pins,
    /// and it is what makes the failure mode survivable.
    #[test]
    fn a_right_answer_alone_in_its_file_stays_on_the_page() {
        // The guard is not decoration. Without it this test reads whatever a
        // concurrently running guarded test has left in the environment, and it
        // first reported the rule as never firing for exactly that reason.
        let _guard =
            kin_core::test_env::EnvVarGuard::set("KIN_LOCATE_COLLISION_CORROBORATION", "1");
        let graph = kin_db::InMemoryGraph::new();
        let right = test_entity("apply", "src/editor/apply.ts", 10, 40);
        graph.upsert_entity(&right).unwrap();
        let mut files = vec![corroboration_file(
            "src/editor/apply.ts",
            0.30,
            vec![corroboration_symbol("apply", 900.0, [10, 40])],
        )];
        // Twelve unrelated rows straddling the demoted score, so where it lands
        // is measured rather than assumed.
        for i in 0..12 {
            let path = format!("src/filler/mod{i}.ts");
            let name = format!("filler_{i}");
            let entity = test_entity(&name, &path, 1, 5);
            graph.upsert_entity(&entity).unwrap();
            files.push(corroboration_file(
                &path,
                0.29 - i as f32 * 0.01,
                vec![corroboration_symbol(&name, 800.0 - i as f32 * 50.0, [1, 5])],
            ));
        }
        let mut result = LocateResult {
            files,
            ..Default::default()
        };
        build_entity_view(
            &mut result,
            &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
            &SnippetOptions::enabled(None).without_bodies(),
            kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
            "how does the editor apply an edit to the open document",
            false,
        )
        .unwrap();
        let position = result
            .entities
            .iter()
            .position(|e| e.name == "apply")
            .expect("the demoted right answer is still in the ranking");
        let shape = result
            .entities
            .iter()
            .map(|e| (e.name.clone(), e.score, e.match_kind))
            .collect::<Vec<_>>();
        assert!(
            position > 0,
            "this fixture only means something if the rule moved it: {shape:?}"
        );
        assert!(
            position < DEFAULT_ENTITY_PAGE_SIZE,
            "a share is not a floor: the demoted right answer must stay on the \
             product's own {}-row default page, landed at {} of {shape:?}",
            DEFAULT_ENTITY_PAGE_SIZE,
            position + 1
        );
        let row = &result.entities[position];
        assert!(
            (row.score - 675.0).abs() < 1.0,
            "three quarters of 900, got {}",
            row.score
        );
    }

    /// A lookup carries no prose, so the rule cannot fire on it and the ranking
    /// is identical with it on and off. The control is the same fixture under a
    /// question, which must differ.
    #[test]
    fn a_lookup_ranking_is_untouched_by_the_corroboration_rule() {
        let graph = kin_db::InMemoryGraph::new();
        let named = test_entity("ignore", "crates/ignore/src/dir.rs", 10, 20);
        graph.upsert_entity(&named).unwrap();
        let other = test_entity("ignore_messages", "crates/core/messages.rs", 10, 20);
        graph.upsert_entity(&other).unwrap();
        let build = |query: &str, on: &str| {
            let _guard =
                kin_core::test_env::EnvVarGuard::set("KIN_LOCATE_COLLISION_CORROBORATION", on);
            let mut result = LocateResult {
                files: vec![
                    corroboration_file(
                        "crates/ignore/src/dir.rs",
                        0.3,
                        vec![corroboration_symbol("ignore", 900.0, [10, 20])],
                    ),
                    corroboration_file(
                        "crates/core/messages.rs",
                        0.2,
                        vec![corroboration_symbol("ignore_messages", 800.0, [10, 20])],
                    ),
                ],
                ..Default::default()
            };
            build_entity_view(
                &mut result,
                &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
                &SnippetOptions::enabled(None).without_bodies(),
                kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
                query,
                false,
            )
            .unwrap();
            result
                .entities
                .iter()
                .map(|e| (e.name.clone(), e.score))
                .collect::<Vec<_>>()
        };
        assert_eq!(
            build("ignore", "1"),
            build("ignore", "0"),
            "a lookup is answered exactly as before"
        );
        assert_ne!(
            build("how does it honour the ignore rules a project sets", "1"),
            build("how does it honour the ignore rules a project sets", "0"),
            "control: the same fixture under a question must differ"
        );
    }

    /// The tie-break must survive a missing `Contains` edge. The edge is
    /// enrichment a freshly built store can lack while the owner type itself
    /// parsed fine: the same kin-db file measured `CodeEmbedder::embed_batch`
    /// at owner mass 14 through its edge on the flagship store and 0 on a
    /// minutes-old store missing the edge, which handed the qb05 tie to
    /// `OpenAiCompatEmbedder::` (mass 5). A graph gap is not evidence the
    /// definition is secondary, so the owner NAME answers when the edge
    /// cannot, and the canonical definition holds rank 1 on both store shapes.
    #[test]
    fn the_owner_mass_tiebreak_survives_a_missing_contains_edge() {
        let relation = |kind: RelationKind, src: EntityId, dst: EntityId| Relation {
            id: RelationId::new(),
            kind,
            src: kin_model::GraphNodeId::Entity(src),
            dst: kin_model::GraphNodeId::Entity(dst),
            confidence: 1.0,
            origin: RelationOrigin::Parsed,
            created_in: None,
            import_source: None,
            evidence: Vec::new(),
        };
        let graph = kin_db::InMemoryGraph::new();
        let canonical_path = "src/embedding/embedder.rs";
        let rival_path = "src/embedding/openai_compat.rs";

        // The canonical method has NO Contains edge, only its owner class
        // sitting in the graph under the qualified prefix name, carrying the
        // larger structural mass.
        let canonical = test_entity("CodeEmbedder::embed_batch", canonical_path, 100, 140);
        let owner = test_entity("CodeEmbedder", canonical_path, 10, 400);
        graph.upsert_entity(&canonical).unwrap();
        graph.upsert_entity(&owner).unwrap();
        for _ in 0..6 {
            let peer = test_entity("peer_helper", canonical_path, 500, 510);
            graph.upsert_entity(&peer).unwrap();
            graph
                .upsert_relation(&relation(RelationKind::Calls, owner.id, peer.id))
                .unwrap();
        }

        // The rival method DOES have its Contains edge, to a smaller owner.
        let rival = test_entity("OpenAiCompatEmbedder::embed_batch", rival_path, 100, 140);
        let rival_owner = test_entity("OpenAiCompatEmbedder", rival_path, 10, 200);
        graph.upsert_entity(&rival).unwrap();
        graph.upsert_entity(&rival_owner).unwrap();
        graph
            .upsert_relation(&relation(RelationKind::Contains, rival_owner.id, rival.id))
            .unwrap();
        graph
            .upsert_relation(&relation(RelationKind::Calls, rival_owner.id, canonical.id))
            .unwrap();

        // File order puts the rival first, exactly the order that shipped the
        // qb05 flip, so only the mass signal can move the canonical hit up.
        let symbol = |name: &str| LocateSymbol {
            name: name.to_string(),
            span: Some([100, 140]),
            score: 450.0,
            kind: "method".to_string(),
            definition: true,
            origin: "text".to_string(),
            cosine: None,
            snippet: None,
        };
        let file = |path: &str, name: &str| LocateFileEntry {
            path: path.to_string(),
            score: 0.2,
            signals: vec![],
            spans: vec![],
            symbols: vec![symbol(name)],
            explain: vec![],
            provenance: None,
            signal_scores: None,
            score_breakdown: None,
            matched_queries: Vec::new(),
        };
        let mut result = LocateResult {
            files: vec![
                file(rival_path, "OpenAiCompatEmbedder::embed_batch"),
                file(canonical_path, "CodeEmbedder::embed_batch"),
            ],
            ..Default::default()
        };
        build_entity_view(
            &mut result,
            &kin_mcp::handlers::common::HeldSourceAuthority::new(&graph, None),
            &SnippetOptions::enabled(None).without_bodies(),
            kin_mcp::handlers::common::EntitySourceScope::WorkspaceHead,
            "embed_batch",
            false,
        )
        .unwrap();
        assert_eq!(
            result.entities[0].name, "CodeEmbedder::embed_batch",
            "the edgeless canonical definition must win through its owner name"
        );
        assert!(
            result.entities[0]
                .provenance
                .origin
                .contains("tie_break=owner_graph_mass:6"),
            "the fallback mass must be the disclosed tie-break, got {:?}",
            result.entities[0].provenance.origin
        );
    }

    #[test]
    fn all_fallback_is_a_verdict_on_the_whole_ranking() {
        let with_kind = |name: &str, kind| {
            let mut entity = mk_locate_entity(name, 1.0, true);
            entity.match_kind = Some(kind);
            entity
        };
        // One name hit anywhere in the ranking means the query found something.
        let found = fuse_locate_results(
            vec!["q0".to_string(), "q1".to_string()],
            vec![
                fusion_result(vec![with_kind("a", LocateMatchKind::TextFallback)]),
                fusion_result(vec![with_kind("b", LocateMatchKind::Name)]),
            ],
            60.0,
        );
        assert!(
            !found.all_fallback,
            "a name hit surfaced by a non-primary variant still counts as found"
        );

        let missed = fuse_locate_results(
            vec!["q0".to_string(), "q1".to_string()],
            vec![
                fusion_result(vec![with_kind("a", LocateMatchKind::TextFallback)]),
                fusion_result(vec![with_kind("b", LocateMatchKind::Semantic)]),
            ],
            60.0,
        );
        assert!(
            missed.all_fallback,
            "a full page of fallbacks is exactly what the caller needs told"
        );

        // An empty result is not a fallback verdict: nothing was returned to
        // mislabel, and reporting one would make "no results" and "wrong
        // results" look alike.
        let empty = fuse_locate_results(
            vec!["q0".to_string(), "q1".to_string()],
            vec![fusion_result(vec![]), fusion_result(vec![])],
            60.0,
        );
        assert!(!empty.all_fallback);
    }

    /// A shared entity can be best-ranked on a descriptive variant and named
    /// only by a lower-ranked sharp variant. Fusion must carry the strongest
    /// match evidence from every contributing variant rather than the record
    /// RRF happened to retain, or it labels a successful fan-out as fallback.
    #[test]
    fn fusion_keeps_a_name_hit_from_a_lower_ranked_variant() {
        let with_kind = |id: &str, kind| {
            let mut entity = fusion_entity(id, "src/shared.rs", 1.0);
            entity.match_kind = Some(kind);
            entity
        };
        let fused = fuse_locate_results(
            vec![
                "where is the request routed".to_string(),
                "route_request".to_string(),
            ],
            vec![
                fusion_result(vec![with_kind("shared", LocateMatchKind::TextFallback)]),
                fusion_result(vec![
                    with_kind("other", LocateMatchKind::Semantic),
                    with_kind("shared", LocateMatchKind::Name),
                ]),
            ],
            60.0,
        );
        let shared = fused
            .entities
            .iter()
            .find(|entity| entity.entity_id == "shared")
            .expect("the shared entity remains in the fused ranking");
        assert_eq!(
            shared.match_kind,
            Some(LocateMatchKind::Name),
            "the lower-ranked sharp variant still named this entity: {:#?}",
            shared.matched_queries
        );
        assert!(
            !fused.all_fallback,
            "one named entity means the multi-query ranking found a named target"
        );
    }

    #[test]
    fn match_kind_serializes_under_the_search_surface_vocabulary() {
        let mut entity = mk_locate_entity("a", 1.0, true);
        entity.match_kind = Some(LocateMatchKind::TextFallback);
        let json = serde_json::to_value(&entity).unwrap();
        assert_eq!(json["match_kind"].as_str(), Some("text_fallback"));
        entity.match_kind = Some(LocateMatchKind::Name);
        assert_eq!(
            serde_json::to_value(&entity).unwrap()["match_kind"].as_str(),
            Some("name")
        );
        // Absent rather than null on a record that predates the field, so an
        // older daemon's payload still deserializes.
        entity.match_kind = None;
        assert!(serde_json::to_value(&entity)
            .unwrap()
            .get("match_kind")
            .is_none());
    }

