    fn entity_page_size_honors_env_override() {
        // Default when unset; floor of 1 when set to 0.
        let _cap = kin_core::test_env::EnvVarGuard::unset("KIN_LOCATE_ENTITY_CAP");
        assert_eq!(entity_page_size(), DEFAULT_ENTITY_PAGE_SIZE);
    }

